def _write_text(path: Path, text: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def _parse_dt(value: Any) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        return None
    if parsed.tzinfo is None:
        return parsed.replace(tzinfo=UTC)
    return parsed.astimezone(UTC)


def _previous_started_at(report_dir: Path) -> datetime | None:
    payload = _previous_watch_payload(report_dir)
    if not payload:
        return None
    return _parse_dt(payload.get("started_at"))


def _previous_watch_payload(report_dir: Path) -> dict[str, Any]:
    latest_path = report_dir / "latest.json"
    try:
        payload = json.loads(latest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(payload, dict):
        return {}
    if payload.get("no_live_order_sent") is not True:
        return {}
    return payload


def _baseline_collection_progress(previous_payload: dict[str, Any]) -> dict[str, Any]:
    baseline = dict(previous_payload.get("baseline_collection_progress") or {})
    if baseline:
        return baseline
    latest_run = dict(previous_payload.get("latest_run") or {})
    return dict(latest_run.get("collection_progress") or {})


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Run safe launch readiness checks repeatedly without live orders.")
    parser.add_argument("--iterations", type=int, default=1)
    parser.add_argument("--interval-seconds", type=float, default=900.0)
    parser.add_argument("--target-hours", type=float, default=24.0)
    parser.add_argument("--quote-samples-per-tick", type=int, default=2)
    parser.add_argument("--force-quote-sample", action="store_true")
    parser.add_argument("--disable-adaptive-quote-cadence", action="store_true")
    parser.add_argument(
        "--sleep-until-next-quote-coverage-window",
        "--sleep-until-next-missing-quote-window",
        dest="sleep_until_next_missing_quote_window",
        action="store_true",
    )
    parser.add_argument("--max-pre-run-wait-seconds", type=float, default=3600.0)
    parser.add_argument("--quote-window-wakeup-buffer-seconds", type=float, default=5.0)
    parser.add_argument("--disable-market-data-refresh-after-quote-window-sleep", action="store_true")
    parser.add_argument("--disable-market-data-refresh-before-evidence-run", action="store_true")
    parser.add_argument("--report-dir", default=DEFAULT_REPORT_DIR)
    parser.add_argument("--evidence-report-root", default=DEFAULT_EVIDENCE_REPORT_ROOT)
    parser.add_argument("--source-backtest-report", default=DEFAULT_SOURCE_BACKTEST_REPORT)
    parser.add_argument("--stress-report", default=DEFAULT_STRESS_REPORT)
    parser.add_argument("--walk-forward-report", default=DEFAULT_WALK_FORWARD_REPORT)
    parser.add_argument("--manual-safety-evidence", default=DEFAULT_MANUAL_EVIDENCE)
    parser.add_argument("--sample-jsonl", default=DEFAULT_SAMPLE_PATH)
    parser.add_argument("--historical-replay-source", default=DEFAULT_HISTORICAL_REPLAY_SOURCE)
    parser.add_argument("--historical-replay-days", type=int, default=1831)
    parser.add_argument("--historical-lifecycle-source", default=DEFAULT_HISTORICAL_LIFECYCLE_REPLAY_SOURCE)
    parser.add_argument(
        "--entry-probe-full-walk-forward-gate-report",
        default=DEFAULT_ENTRY_PROBE_FULL_WALK_FORWARD_GATE_REPORT,
    )
    parser.add_argument("--canary-max-notional-usdt", type=float, default=0.0)
    parser.add_argument("--canary-max-leverage", type=float, default=10.0)
    parser.add_argument("--canary-max-daily-loss-usdt", type=float, default=0.0)
    parser.add_argument("--canary-risk-caps-json", default=DEFAULT_CANARY_RISK_CAPS_PATH)
    parser.add_argument("--microstructure-recent-hours", type=float, default=24.0)
    parser.add_argument(
        "--disable-btcusdc-parallel-shadow-lane",
        dest="enable_btcusdc_parallel_shadow_lane",
        action="store_false",
        default=True,
        help="Disable the informational BTCUSDC no-live parallel shadow lane.",
    )
    parser.add_argument("--btcusdc-parallel-symbol", default=DEFAULT_BTCUSDC_PARALLEL_SYMBOL)
    parser.add_argument("--btcusdc-parallel-sample-jsonl", default=DEFAULT_BTCUSDC_PARALLEL_SAMPLE_PATH)
    parser.add_argument(
        "--btcusdc-parallel-canary-risk-caps-json",
        default=DEFAULT_BTCUSDC_PARALLEL_CANARY_RISK_CAPS_PATH,
    )
    parser.add_argument(
        "--sleep-until-next-btcusdc-parallel-quote-window",
        action="store_true",
        help="When the BTCUSDC informational lane is enabled, wait until its next standard quote window.",
    )
    parser.add_argument("--quiet", action="store_true")
    return parser.parse_args()


def _run_once(
    args: argparse.Namespace,
    *,
    iteration: int,
    generated_at: datetime,
    observed_hours: float,
    refresh_market_data_before_run: bool = True,
    force_quote_sample: bool = False,
    symbol: str | None = None,
    sample_jsonl: Path | None = None,
    evidence_label: str | None = None,
    canary_risk_caps_json: str | None = None,
) -> dict[str, Any]:
    evidence_root = _resolve(args.evidence_report_root)
    normalized_symbol = str(symbol or EXPECTED_SYMBOL).upper()
    normalized_label = "".join(
        char if char.isalnum() or char in {"-", "_"} else "_"
        for char in str(evidence_label or "").strip()
    )
    evidence_stem = f"market_state_rotation_v6_launch_shadow_watch_{generated_at:%Y%m%d_%H%M%S}"
    if normalized_label:
        evidence_stem = f"{evidence_stem}_{normalized_label}"
    evidence_dir = evidence_root / f"{evidence_stem}_i{iteration:03d}"
    manual_path = _resolve(args.manual_safety_evidence) if args.manual_safety_evidence else None
    effective_force_quote_sample = bool(args.force_quote_sample) or bool(force_quote_sample)
    sample_jsonl_path = sample_jsonl if sample_jsonl is not None else _resolve(args.sample_jsonl)
    effective_canary_caps_json = (
        str(canary_risk_caps_json)
        if canary_risk_caps_json is not None
        else str(getattr(args, "canary_risk_caps_json", "") or "")
    )
    report = run_evidence_cycle(
        source_backtest_report_path=_resolve(args.source_backtest_report),
        stress_report_path=_resolve(args.stress_report),
        walk_forward_report_path=_resolve(args.walk_forward_report),
        manual_evidence_path=manual_path,
        sample_jsonl=sample_jsonl_path,
        report_dir=evidence_dir,
        symbol=normalized_symbol,
        quote_samples_per_tick=max(0, int(args.quote_samples_per_tick)),
        adaptive_quote_cadence=not bool(args.disable_adaptive_quote_cadence),
        force_quote_sample=effective_force_quote_sample,
        historical_evidence_replay=True,
        refresh_market_data_before_run=bool(refresh_market_data_before_run),
        historical_replay_source_path=_resolve(args.historical_replay_source),
        historical_replay_days=max(1, int(args.historical_replay_days)),
        historical_lifecycle_replay=True,
        historical_lifecycle_source_path=_resolve(args.historical_lifecycle_source),
        entry_probe_full_walk_forward_gate_report_path=(
            _resolve(getattr(args, "entry_probe_full_walk_forward_gate_report", None))
            if getattr(args, "entry_probe_full_walk_forward_gate_report", None)
            else None
        ),
        canary_max_notional_usdt=max(0.0, float(args.canary_max_notional_usdt)),
        canary_max_leverage=max(0.0, float(args.canary_max_leverage)),
        canary_max_daily_loss_usdt=max(0.0, float(args.canary_max_daily_loss_usdt)),
        canary_risk_caps_path=_resolve(effective_canary_caps_json) if effective_canary_caps_json else None,
        shadow_runtime_observed_hours=max(0.0, float(observed_hours or 0.0)),
        shadow_runtime_required_hours=max(0.0, float(args.target_hours or 0.0)),
    )
    return {
        "iteration": iteration,
        "generated_at": generated_at.isoformat(),
        "symbol": normalized_symbol,
        "sample_jsonl": _display_path(sample_jsonl_path),
        "shadow_runtime_observed_hours": round(max(0.0, float(observed_hours or 0.0)), 4),
        "shadow_runtime_required_hours": max(0.0, float(args.target_hours or 0.0)),
        "evidence_report_dir": _display_path(evidence_dir),
        "evidence_report": _display_path(evidence_dir / EVIDENCE_REPORT_NAME),
        "overall_status": report.get("overall_status"),
        "no_live_order_sent": report.get("no_live_order_sent") is True,
        "decision_state": dict(report.get("decision_state") or {}),
        "entry_quality": dict(report.get("entry_quality") or {}),
        "collection_progress": dict(report.get("collection_progress") or {}),
        "readiness_progress": dict(report.get("readiness_progress") or {}),
        "execution_parity_journal": dict(report.get("execution_parity_journal") or {}),
        "execution_parity_collection_plan": dict(report.get("execution_parity_collection_plan") or {}),
        "paper_bridge_apply_gate": dict(report.get("paper_bridge_apply_gate") or {}),
        "pre_apply_backup_plan": dict(report.get("pre_apply_backup_plan") or {}),
        "quote_cadence_preflight": dict(report.get("quote_cadence_preflight") or {}),
        "pre_run_market_data_refresh": dict(report.get("pre_run_market_data_refresh") or {}),
        "market_data_refresh_plan": dict(report.get("market_data_refresh_plan") or {}),
        "signal_wait_plan": dict(report.get("signal_wait_plan") or {}),
        "launch_readiness": dict(report.get("launch_readiness") or {}),
        "launch_safety_controls": dict(report.get("launch_safety_controls") or {}),
        "historical_gate_substitution": dict(report.get("historical_gate_substitution") or {}),
        "canary_risk_caps_config": dict(report.get("canary_risk_caps_config") or {}),
    }


def _parallel_btcusdc_shadow_enabled(args: argparse.Namespace) -> bool:
    return bool(getattr(args, "enable_btcusdc_parallel_shadow_lane", False))


def _parallel_btcusdc_sample_path(args: argparse.Namespace) -> Path:
    configured = str(getattr(args, "btcusdc_parallel_sample_jsonl", "") or "").strip()
    return _resolve(configured or DEFAULT_BTCUSDC_PARALLEL_SAMPLE_PATH)


def _parallel_btcusdc_symbol(args: argparse.Namespace) -> str:
    return str(getattr(args, "btcusdc_parallel_symbol", "") or DEFAULT_BTCUSDC_PARALLEL_SYMBOL).upper()


def _parallel_btcusdc_canary_risk_caps_json(args: argparse.Namespace) -> str:
    return str(
        getattr(
            args,
            "btcusdc_parallel_canary_risk_caps_json",
            DEFAULT_BTCUSDC_PARALLEL_CANARY_RISK_CAPS_PATH,
        )
        or ""
    )


def _parallel_btcusdc_quote_capture_command(args: argparse.Namespace, *, report_dir: str) -> str:
    symbol = _parallel_btcusdc_symbol(args)
    sample_path = _display_path(_parallel_btcusdc_sample_path(args))
    caps_path = _parallel_btcusdc_canary_risk_caps_json(args)
    parts = [
        ".venv/bin/python",
        "scripts/run_market_state_rotation_v6_evidence_cycle.py",
        "--symbol",
        symbol,
        "--sample-jsonl",
        sample_path,
        "--quote-samples-per-tick",
        str(max(1, int(getattr(args, "quote_samples_per_tick", 2) or 2))),
        "--refresh-market-data-before-run",
        "--historical-evidence-replay",
        "--historical-lifecycle-replay",
        "--report-dir",
        report_dir,
    ]
    if caps_path:
        parts.extend(["--canary-risk-caps-json", caps_path])
    return " ".join(shlex.quote(part) for part in parts)


def _btc_usdc_parallel_shadow_lane_summary(
    *,
    primary_run: dict[str, Any] | None,
    candidate_run: dict[str, Any] | None,
    candidate_microstructure_watch: dict[str, Any] | None = None,
    enabled: bool,
) -> dict[str, Any]:
    primary = dict(primary_run or {})
    candidate = dict(candidate_run or {})
    candidate_collection = dict(candidate.get("collection_progress") or {})
    primary_collection = dict(primary.get("collection_progress") or {})
    candidate_launch = dict(candidate.get("launch_readiness") or {})
    candidate_parity = dict(candidate.get("execution_parity_journal") or {})
    candidate_parity_plan = dict(candidate_parity.get("collection_plan") or {})
    candidate_contract = dict(candidate_parity.get("contract_report") or {})
    candidate_contract_summary = dict(
        candidate_contract.get("summary")
        or candidate_contract.get("contract_summary")
        or candidate_parity.get("contract_summary")
        or {}
    )
    candidate_canary_caps = dict(candidate.get("canary_risk_caps_config") or {})
    candidate_canary_safeguards = dict(candidate_canary_caps.get("safeguards") or {})
    candidate_canary_required = dict(candidate_canary_caps.get("required_safeguards") or {})
    candidate_micro = dict(candidate_microstructure_watch or {})
    candidate_coverage_plan = dict(candidate_micro.get("coverage_plan") or {})
    candidate_bridge_gate = dict(candidate.get("paper_bridge_apply_gate") or {})
    candidate_preflight = dict(candidate.get("quote_cadence_preflight") or {})
    candidate_symbol = str(candidate.get("symbol") or DEFAULT_BTCUSDC_PARALLEL_SYMBOL).upper()
    contract_symbol = str(candidate_contract_summary.get("symbol") or "").upper()
    candidate_symbol_contract_mismatch = contract_symbol not in {"", candidate_symbol}
    candidate_quote_capture_command = str(candidate_coverage_plan.get("quote_capture_command") or "")
    requested_quote_samples_per_tick = _int_or_default(
        candidate_preflight.get("requested_quote_samples_per_tick"),
        0,
    )
    if requested_quote_samples_per_tick <= 0 and candidate_quote_capture_command:
        try:
            command_parts = shlex.split(candidate_quote_capture_command)
            quote_tick_arg = command_parts.index("--quote-samples-per-tick")
            requested_quote_samples_per_tick = _int_or_default(
                command_parts[quote_tick_arg + 1],
                0,
            )
        except (ValueError, IndexError):
            requested_quote_samples_per_tick = 0
    expected_rows_per_successful_capture = max(requested_quote_samples_per_tick, 0) * 2
    candidate_observed = _int_or_default(candidate_collection.get("quote_observed"), 0)
    candidate_missing = _int_or_default(candidate_collection.get("quote_missing_samples"), 0)
    candidate_distinct_hours = _int_or_default(candidate_collection.get("quote_distinct_hours"), 0)
    candidate_missing_distinct_hours = max(
        _int_or_default(candidate_coverage_plan.get("remaining_distinct_hours"), 0),
        0,
    )
    next_kind = str(candidate_coverage_plan.get("next_quote_coverage_kind") or "")
    next_success_advances_distinct_hour = next_kind in {
        "missing_utc_hour_bucket",
        "missing_hour_of_day_balance_bucket",
    }
    expected_distinct_hour_delta = 1 if next_success_advances_distinct_hour and candidate_missing_distinct_hours > 0 else 0
    quote_capture_runbook_status = (
        "coverage_complete"
        if candidate_coverage_plan.get("status") == "coverage_complete"
        else "capture_current_standard_window_now"
        if candidate_coverage_plan.get("standard_capture_window_open") is True
        else "wait_for_next_standard_capture_window"
        if candidate_coverage_plan.get("next_quote_coverage_at")
        else "quote_capture_window_unknown"
    )
    status = (
        "parallel_btcusdc_shadow_lane_collecting"
        if enabled and candidate
        else "parallel_btcusdc_shadow_lane_enabled_no_run"
        if enabled
        else "parallel_btcusdc_shadow_lane_disabled"
    )
    return {
        "schema_version": "market_state_rotation_v6_btcusdc_parallel_shadow_lane_v1",
        "status": status,
        "purpose": "evaluate_fee_optimized_btcusdc_maker_only_candidate_without_launch_promotion",
        "launch_gate_effect": "informational_only_does_not_unlock_btcusdt_launch_or_live_trading",
        "primary_symbol": str(primary.get("symbol") or EXPECTED_SYMBOL).upper() if primary else EXPECTED_SYMBOL,
        "candidate_symbol": candidate_symbol if candidate else DEFAULT_BTCUSDC_PARALLEL_SYMBOL,
        "candidate_readiness_status": (
            "quote_shadow_collecting_contract_scope_still_btcusdt"
            if candidate_symbol_contract_mismatch
            else "quote_shadow_collecting_candidate_scope_aligned"
            if candidate
            else "not_started"
        ),
        "candidate_sample_jsonl": candidate.get("sample_jsonl"),
        "candidate_evidence_report": candidate.get("evidence_report"),
        "candidate_evidence_report_dir": candidate.get("evidence_report_dir"),
        "candidate_canary_risk_caps": {
            "status": candidate_canary_caps.get("status"),
            "configured": candidate_canary_caps.get("configured"),
            "path": candidate_canary_caps.get("path"),
            "path_exists": candidate_canary_caps.get("path_exists"),
            "required_scope_symbol": candidate_canary_required.get("scope_symbol"),
            "configured_scope_symbol": candidate_canary_safeguards.get("scope_symbol"),
            "errors": list(candidate_canary_caps.get("errors") or []),
            "order_submission_allowed": candidate_canary_caps.get("order_submission_allowed") is True,
            "no_live_order_sent": candidate_canary_caps.get("no_live_order_sent") is not False,
        },
        "candidate_quote_microstructure_watch": candidate_micro,
        "candidate_quote_coverage_plan": {
            "status": candidate_coverage_plan.get("status"),
            "remaining_quote_samples": candidate_coverage_plan.get("remaining_quote_samples"),
            "remaining_calendar_days": candidate_coverage_plan.get("remaining_calendar_days"),
            "remaining_distinct_hours": candidate_coverage_plan.get("remaining_distinct_hours"),
            "remaining_hour_of_day_bucket_count": candidate_coverage_plan.get(
                "remaining_hour_of_day_bucket_count"
            ),
            "current_utc_date_missing": candidate_coverage_plan.get("current_utc_date_missing"),
            "current_utc_hour_missing": candidate_coverage_plan.get("current_utc_hour_missing"),
            "sample_count_incomplete": candidate_coverage_plan.get("sample_count_incomplete"),
            "time_coverage_incomplete": candidate_coverage_plan.get("time_coverage_incomplete"),
            "standard_capture_window_open": candidate_coverage_plan.get("standard_capture_window_open"),
            "standard_capture_would_skip_duplicate_window": candidate_coverage_plan.get(
                "standard_capture_would_skip_duplicate_window"
            ),
            "force_quote_sample_available": candidate_coverage_plan.get("force_quote_sample_available"),
            "force_quote_sample_policy": candidate_coverage_plan.get("force_quote_sample_policy"),
            "next_quote_coverage_kind": candidate_coverage_plan.get("next_quote_coverage_kind"),
            "next_quote_coverage_at": candidate_coverage_plan.get("next_quote_coverage_at"),
            "next_quote_coverage_kst_at": candidate_coverage_plan.get("next_quote_coverage_kst_at"),
            "next_quote_coverage_wait_minutes": candidate_coverage_plan.get(
                "next_quote_coverage_wait_minutes"
            ),
            "earliest_calendar_completion_kst": candidate_coverage_plan.get(
                "earliest_calendar_completion_kst"
            ),
            "can_collect_now": candidate_coverage_plan.get("can_collect_now"),
            "recommended_action": candidate_coverage_plan.get("recommended_action"),
            "quote_capture_command": candidate_coverage_plan.get("quote_capture_command"),
            "no_live_order_sent": candidate_coverage_plan.get("no_live_order_sent") is not False,
        },
        "candidate_quote_capture_runbook": {
            "status": quote_capture_runbook_status,
            "standard_capture_window_open": candidate_coverage_plan.get("standard_capture_window_open") is True,
            "standard_capture_would_skip_duplicate_window": candidate_coverage_plan.get(
                "standard_capture_would_skip_duplicate_window"
            )
            is True,
            "next_standard_capture_utc_at": candidate_coverage_plan.get("next_quote_coverage_at"),
            "next_standard_capture_kst_at": candidate_coverage_plan.get("next_quote_coverage_kst_at"),
            "next_standard_capture_wait_minutes": candidate_coverage_plan.get(
                "next_quote_coverage_wait_minutes"
            ),
            "next_standard_capture_kind": candidate_coverage_plan.get("next_quote_coverage_kind"),
            "standard_capture_command": candidate_quote_capture_command or None,
            "command_includes_market_data_refresh": "--refresh-market-data-before-run"
            in candidate_quote_capture_command,
            "command_includes_apply_paper_bridge": "--apply-paper-bridge" in candidate_quote_capture_command,
            "command_includes_live_flag": "--live" in candidate_quote_capture_command,
            "requested_quote_samples_per_tick": requested_quote_samples_per_tick,
            "expected_rows_per_successful_capture": expected_rows_per_successful_capture,
            "expected_quote_observed_after_successful_capture": candidate_observed
            + expected_rows_per_successful_capture,
            "expected_remaining_samples_after_successful_capture": max(
                candidate_missing - expected_rows_per_successful_capture,
                0,
            ),
            "expected_distinct_hour_delta_after_successful_capture": expected_distinct_hour_delta,
            "expected_distinct_hours_after_successful_capture": candidate_distinct_hours
            + expected_distinct_hour_delta,
            "expected_remaining_distinct_hours_after_successful_capture": max(
                candidate_missing_distinct_hours - expected_distinct_hour_delta,
                0,
            ),
            "force_duplicate_window_policy": candidate_coverage_plan.get("force_quote_sample_policy"),
            "repeat_policy": (
                "run_one_standard_capture_after_each_missing_utc_hour_window_until_300_rows_"
                "24_distinct_hours_and_30_calendar_days_are_observed"
            ),
            "order_submission_allowed": False,
            "no_live_order_sent": True,
        },
        "fee_model": {
            "venue": "binance_usdc_margined_perpetuals",
            "maker_fee_rate": 0.0,
            "maker_fee_unit": "fraction",
            "maker_fee_bps": 0.0,
            "requires_post_only_or_maker_only_reject": True,
            "taker_fee_not_zero_assumption": True,
            "fee_promotion_status": "operator_verified_until_further_notice_2026_03_30_update",
            "fee_model_is_promotional_and_must_be_rechecked_before_live": True,
        },
        "candidate_quote_progress": {
            "observed": candidate_collection.get("quote_observed"),
            "required": candidate_collection.get("quote_required"),
            "missing_samples": candidate_collection.get("quote_missing_samples"),
            "distinct_hours": candidate_collection.get("quote_distinct_hours"),
            "calendar_days": candidate_collection.get("quote_calendar_days"),
            "captured_quote_rows_this_cycle": candidate_collection.get("captured_quote_rows_this_cycle"),
            "quote_cadence_decision": candidate_preflight.get("decision"),
            "effective_quote_samples_per_tick": candidate_preflight.get(
                "effective_quote_samples_per_tick"
            ),
        },
        "primary_quote_progress": {
            "observed": primary_collection.get("quote_observed"),
            "required": primary_collection.get("quote_required"),
            "missing_samples": primary_collection.get("quote_missing_samples"),
            "distinct_hours": primary_collection.get("quote_distinct_hours"),
            "calendar_days": primary_collection.get("quote_calendar_days"),
        },
        "candidate_gates": {
            "launch_status": candidate_launch.get("status"),
            "next_blocker": dict(candidate_launch.get("next_blocker") or {}).get("gate"),
            "fresh_signal_available": dict(candidate.get("decision_state") or {}).get("fresh_signal") is True,
            "paper_apply_gate_status": candidate_bridge_gate.get("status"),
            "execution_parity_status": candidate_parity.get("status"),
            "execution_parity_sample_count": candidate_parity_plan.get("sample_count")
            if candidate_parity_plan
            else candidate_contract_summary.get("sample_count"),
            "execution_parity_required_samples": candidate_parity_plan.get("required_samples")
            if candidate_parity_plan
            else candidate_contract_summary.get("min_sample_count"),
            "execution_parity_missing_samples": candidate_parity_plan.get("missing_samples"),
            "execution_parity_contract_symbol": candidate_contract_summary.get("symbol"),
            "candidate_symbol_contract_mismatch": candidate_symbol_contract_mismatch,
            "canary_risk_caps_status": candidate_canary_caps.get("status"),
            "canary_risk_caps_configured": candidate_canary_caps.get("configured"),
            "canary_risk_caps_path": candidate_canary_caps.get("path"),
        },
        "comparison": {
            "quote_observed_delta_candidate_minus_primary": (
                int(candidate_collection.get("quote_observed") or 0)
                - int(primary_collection.get("quote_observed") or 0)
            )
            if candidate or primary
            else None,
            "candidate_collecting_separate_quote_book": bool(candidate),
            "candidate_not_used_for_current_launch_readiness": True,
            "btc_usdt_watch_preserved": True,
        },
        "safety": {
            "shadow_only": True,
            "paper_apply_allowed": False,
            "auto_apply_allowed": False,
            "live_order_submission_allowed": False,
            "order_submission_allowed": False,
            "force_signal_allowed": False,
            "no_live_order_sent": candidate.get("no_live_order_sent") is not False
            and primary.get("no_live_order_sent") is not False,
        },
        "no_live_order_sent": candidate.get("no_live_order_sent") is not False
        and primary.get("no_live_order_sent") is not False,
    }


def _watch_progress(runs: list[dict[str, Any]], *, baseline_collection: dict[str, Any] | None = None) -> dict[str, Any]:
    if not runs:
        return {
            "fresh_signal_seen": False,
            "paper_apply_available_seen": False,
            "paper_only_rehearsal_statuses_seen": [],
            "paper_only_rehearsal_armed_seen": False,
            "paper_only_rehearsal_available_seen": False,
            "paper_only_rehearsal_first_completed_seen": False,
            "paper_only_max_substitution_ready_seen": False,
            "tiny_canary_ready_seen": False,
        }
    first_collection = dict(baseline_collection or runs[0].get("collection_progress") or {})
    latest_collection = dict(runs[-1].get("collection_progress") or {})
    latest_parity_plan = dict(runs[-1].get("execution_parity_collection_plan") or {})
    launch_statuses = [str(dict(run.get("launch_readiness") or {}).get("status") or "") for run in runs]
    paper_only_statuses = [
        str(dict(dict(run.get("launch_readiness") or {}).get("paper_only_rehearsal") or {}).get("status") or "")
        for run in runs
    ]
    next_blockers = [
        str(dict(dict(run.get("launch_readiness") or {}).get("next_blocker") or {}).get("gate") or "")
        for run in runs
    ]
    fresh_signal_seen = any(
        dict(run.get("paper_bridge_apply_gate") or {}).get("fresh_signal") is True
        for run in runs
    )
    paper_apply_available_seen = any(
        dict(run.get("paper_bridge_apply_gate") or {}).get("can_request_paper_apply_now") is True
        for run in runs
    )
    paper_only_rehearsal_armed_seen = any(
        dict(dict(run.get("launch_readiness") or {}).get("paper_only_rehearsal") or {}).get("armed") is True
        for run in runs
    )
    paper_only_rehearsal_available_seen = any(
        dict(dict(run.get("launch_readiness") or {}).get("paper_only_rehearsal") or {}).get(
            "current_rehearsal_available"
        )
        is True
        for run in runs
    )
    paper_only_rehearsal_first_completed_seen = any(
        dict(dict(run.get("launch_readiness") or {}).get("paper_only_rehearsal") or {}).get(
            "first_rehearsal_event_completed"
        )
        is True
        for run in runs
    )
    paper_only_max_substitution_ready_seen = any(
        dict(dict(run.get("launch_readiness") or {}).get("paper_only_rehearsal") or {}).get(
            "max_substitution_ready"
        )
        is True
        for run in runs
    )
    tiny_canary_ready_seen = any(
        dict(run.get("launch_readiness") or {}).get("tiny_canary_evidence_ready") is True
        for run in runs
    )
    def _int_value(payload: dict[str, Any], key: str) -> int:
        try:
            return int(payload.get(key) or 0)
        except (TypeError, ValueError):
            return 0

    quote_delta = _int_value(latest_collection, "quote_observed") - _int_value(first_collection, "quote_observed")
    hour_delta = _int_value(latest_collection, "quote_distinct_hours") - _int_value(first_collection, "quote_distinct_hours")
    execution_parity_delta = _int_value(latest_collection, "execution_parity_journal_rows") - _int_value(
        first_collection,
        "execution_parity_journal_rows",
    )
    return {
        "launch_statuses_seen": sorted(set(item for item in launch_statuses if item)),
        "paper_only_rehearsal_statuses_seen": sorted(set(item for item in paper_only_statuses if item)),
        "next_blockers_seen": sorted(set(item for item in next_blockers if item)),
        "fresh_signal_seen": fresh_signal_seen,
        "paper_apply_available_seen": paper_apply_available_seen,
        "paper_only_rehearsal_armed_seen": paper_only_rehearsal_armed_seen,
        "paper_only_rehearsal_available_seen": paper_only_rehearsal_available_seen,
        "paper_only_rehearsal_first_completed_seen": paper_only_rehearsal_first_completed_seen,
        "paper_only_max_substitution_ready_seen": paper_only_max_substitution_ready_seen,
        "tiny_canary_ready_seen": tiny_canary_ready_seen,
        "quote_observed_start": _int_value(first_collection, "quote_observed"),
        "quote_observed_latest": _int_value(latest_collection, "quote_observed"),
        "quote_observed_delta": quote_delta,
        "quote_progress_state": "progressing" if quote_delta > 0 else "no_new_quote_rows_since_watch_baseline",
        "quote_distinct_hours_start": _int_value(first_collection, "quote_distinct_hours"),
        "quote_distinct_hours_latest": _int_value(latest_collection, "quote_distinct_hours"),
        "quote_distinct_hours_delta": hour_delta,
        "quote_hour_progress_state": "progressing" if hour_delta > 0 else "no_new_utc_hour_since_watch_baseline",
        "paper_fill_rows_latest": _int_value(latest_collection, "paper_fill_rows"),
        "execution_parity_journal_rows_latest": _int_value(latest_collection, "execution_parity_journal_rows"),
        "execution_parity_journal_rows_delta": execution_parity_delta,
        "execution_parity_missing_samples_latest": _int_value(latest_collection, "execution_parity_missing_samples"),
        "execution_parity_passed_latest": latest_collection.get("execution_parity_passed") is True,
        "execution_parity_progress_state": (
            "progressing" if execution_parity_delta > 0 else "no_new_execution_parity_rows_since_watch_baseline"
        ),
        "execution_parity_collection_status_latest": latest_parity_plan.get("status"),
        "execution_parity_events_needed_latest": _int_value(
            latest_parity_plan,
            "estimated_future_paper_apply_events_needed",
        ),
        "execution_parity_events_needed_after_current_apply_latest": _int_value(
            latest_parity_plan,
            "estimated_events_needed_after_current_creditable_apply",
        ),
        "execution_parity_will_credit_current_apply_latest": (
            latest_parity_plan.get("will_credit_current_apply_after_operator_review") is True
        ),
        "execution_parity_creditable_actions_latest": list(
            latest_parity_plan.get("currently_creditable_actions") or []
        ),
        "execution_parity_next_step_latest": latest_parity_plan.get("next_step"),
        "execution_parity_non_substitutable_latest": latest_parity_plan.get("non_substitutable") is True,
    }


def _fresh_signal_opportunity_memory(
    *,
    progress: dict[str, Any],
    latest: dict[str, Any],
    first_fresh_signal_paper_apply_runbook: dict[str, Any],
    execution_parity_status_summary: dict[str, Any],
    previous_payload: dict[str, Any] | None,
    generated_at: datetime,
) -> dict[str, Any]:
    progress_state = dict(progress or {})
    latest_gate = dict(latest.get("paper_bridge_apply_gate") or {})
    latest_preflight = dict(latest_gate.get("execution_parity_preflight") or {})
    runbook = dict(first_fresh_signal_paper_apply_runbook or {})
    parity = dict(execution_parity_status_summary or {})
    previous = dict(previous_payload or {})
    previous_memory = dict(previous.get("fresh_signal_opportunity_memory") or {})
    previous_runbook = dict(previous.get("first_fresh_signal_paper_apply_runbook") or {})
    previous_fresh = dict(
        previous.get("fresh_signal_status") or previous.get("fresh_signal") or {}
    )
    previous_paper = dict(
        previous.get("paper_apply_status") or previous.get("paper_apply") or {}
    )
    previous_latest = dict(previous.get("latest_run") or {})
    previous_gate = dict(previous_latest.get("paper_bridge_apply_gate") or {})
    current_fresh_signal = (
        progress_state.get("fresh_signal_seen") is True
        or latest_gate.get("fresh_signal") is True
        or runbook.get("fresh_signal") is True
    )
    current_paper_apply_available = (
        progress_state.get("paper_apply_available_seen") is True
        or latest_gate.get("can_request_paper_apply_now") is True
        or runbook.get("paper_apply_allowed_now") is True
    )

    def _age_minutes(last_seen_at: Any) -> float | None:
        parsed = _parse_dt(last_seen_at)
        if parsed is None:
            return None
        age_seconds = max(
            (generated_at.astimezone(UTC) - parsed.astimezone(UTC)).total_seconds(),
            0.0,
        )
        return round(age_seconds / 60.0, 4)

    if current_fresh_signal:
        source_event_key = runbook.get("source_event_key") or latest_preflight.get("source_event_key")
        source_event_ts = runbook.get("source_event_ts") or latest_preflight.get("source_event_ts")
        status = (
            "current_fresh_signal_paper_apply_ready"
            if current_paper_apply_available
            else "current_fresh_signal_seen_waiting_for_paper_apply_gate"
        )
        return {
            "status": status,
            "ever_seen": True,
            "current_window_active": True,
            "current_fresh_signal": True,
            "paper_apply_available_now": current_paper_apply_available,
            "last_seen_at": generated_at.isoformat(),
            "last_seen_at_kst": generated_at.astimezone(KST).isoformat(),
            "last_seen_source": "current_watch",
            "source_event_key": source_event_key,
            "source_event_ts": source_event_ts,
            "bridge_action": runbook.get("bridge_action") or latest_gate.get("bridge_action"),
            "apply_command_allowed_now": runbook.get("apply_command_allowed_now"),
            "apply_command_when_gate_allows": runbook.get("apply_command_when_gate_allows"),
            "post_apply_execution_parity_review_command": runbook.get(
                "post_apply_execution_parity_review_command"
            ),
            "execution_parity_missing_samples": parity.get("missing_samples"),
            "safe_next_action": (
                "operator_review_current_signal_before_manual_paper_apply"
                if current_paper_apply_available
                else "inspect_paper_bridge_apply_gate_without_forcing_entry"
            ),
            "stale_signal_apply_allowed": False,
            "auto_apply_allowed": False,
            "force_signal_allowed": False,
            "order_submission_allowed": False,
            "no_live_order_sent": True,
        }

    previous_signal_seen = (
        previous_memory.get("ever_seen") is True
        or previous_fresh.get("seen_during_watch") is True
        or previous_fresh.get("available") is True
        or previous_runbook.get("fresh_signal") is True
        or previous_gate.get("fresh_signal") is True
    )
    if not previous_signal_seen:
        return {
            "status": "no_fresh_signal_seen_yet",
            "ever_seen": False,
            "current_window_active": False,
            "current_fresh_signal": False,
            "paper_apply_available_now": False,
            "last_seen_at": None,
            "last_seen_at_kst": None,
            "last_seen_source": None,
            "safe_next_action": "monitor_fresh_signal_without_forcing_entry",
            "stale_signal_apply_allowed": False,
            "auto_apply_allowed": False,
            "force_signal_allowed": False,
            "order_submission_allowed": False,
            "no_live_order_sent": True,
        }

    last_seen_at = (
        previous_memory.get("last_seen_at")
        or previous_runbook.get("packet_generated_at")
        or previous.get("completed_at")
        or previous.get("generated_at")
    )
    previous_apply_ready = (
        previous_memory.get("paper_apply_available_now") is True
        or previous_paper.get("seen_during_watch") is True
        or previous_paper.get("allowed_now") is True
        or previous_runbook.get("paper_apply_allowed_now") is True
        or previous_gate.get("can_request_paper_apply_now") is True
    )
    source_event_key = (
        previous_memory.get("source_event_key")
        or previous_runbook.get("source_event_key")
        or dict(previous_gate.get("execution_parity_preflight") or {}).get("source_event_key")
    )
    source_event_ts = (
        previous_memory.get("source_event_ts")
        or previous_runbook.get("source_event_ts")
        or dict(previous_gate.get("execution_parity_preflight") or {}).get("source_event_ts")
    )
    last_seen_dt = _parse_dt(last_seen_at)
    last_seen_kst = last_seen_dt.astimezone(KST).isoformat() if last_seen_dt is not None else None
    status = (
        "previous_paper_apply_window_elapsed_without_recorded_apply"
        if previous_apply_ready
        else "previous_fresh_signal_expired_before_paper_apply_gate_opened"
    )
    return {
        "status": status,
        "ever_seen": True,
        "current_window_active": False,
        "current_fresh_signal": False,
        "paper_apply_available_now": False,
        "previous_paper_apply_available": previous_apply_ready,
        "last_seen_at": last_seen_at,
        "last_seen_at_kst": last_seen_kst,
        "last_seen_age_minutes": _age_minutes(last_seen_at),
        "last_seen_source": "previous_watch",
        "carried_forward_from_previous_watch": True,
        "source_event_key": source_event_key,
        "source_event_ts": source_event_ts,
        "bridge_action": (
            previous_memory.get("bridge_action")
            or previous_runbook.get("bridge_action")
            or previous_gate.get("bridge_action")
        ),
        "apply_command_allowed_now": None,
        "apply_command_when_gate_allows": (
            previous_memory.get("apply_command_when_gate_allows")
            or previous_runbook.get("apply_command_when_gate_allows")
        ),
        "post_apply_execution_parity_review_command": (
            previous_memory.get("post_apply_execution_parity_review_command")
            or previous_runbook.get("post_apply_execution_parity_review_command")
        ),
        "execution_parity_missing_samples": parity.get("missing_samples"),
        "expired_window_outcome": (
            "paper_apply_was_available_but_no_reviewed_apply_row_recorded"
            if previous_apply_ready
            else "fresh_signal_was_observed_but_apply_gate_never_opened_in_time"
        ),
        "safe_next_action": "wait_for_next_fresh_signal_and_rerun_pre_apply_dry_run",
        "stale_signal_apply_allowed": False,
        "auto_apply_allowed": False,
        "force_signal_allowed": False,
        "order_submission_allowed": False,
        "no_live_order_sent": True,
    }


def _number_or_none(value: Any) -> float | None:
    try:
        parsed = float(value)
    except (TypeError, ValueError):
        return None
    return parsed if parsed == parsed and parsed not in {float("inf"), float("-inf")} else None


def _paper_rehearsal_fast_signal_monitor_plan(
    latest: dict[str, Any],
    *,
    generated_at: datetime,
    previous_payload: dict[str, Any] | None = None,
) -> dict[str, Any]:
    signal_wait = dict(latest.get("signal_wait_plan") or {})
    launch = dict(latest.get("launch_readiness") or {})
    rehearsal = dict(launch.get("paper_only_rehearsal") or {})
    remaining = {str(item) for item in list(rehearsal.get("remaining_gates") or [])}
    armed_waiting = (
        rehearsal.get("armed") is True
        and "current_fresh_signal" in remaining
        and signal_wait.get("fresh_signal") is not True
    )
    if not armed_waiting:
        return signal_wait
    current_recommended = _number_or_none(signal_wait.get("recommended_monitor_interval_minutes"))
    fast_minutes = PAPER_REHEARSAL_FAST_SIGNAL_MONITOR_MINUTES
    effective_minutes = min(current_recommended, fast_minutes) if current_recommended else fast_minutes
    current_event_key = str(signal_wait.get("latest_event_ts") or "").strip()
    previous_signal_wait = dict(dict(previous_payload or {}).get("latest_run") or {}).get(
        "signal_wait_plan"
    )
    previous_signal_wait = dict(previous_signal_wait or {})
    previous_event_key = str(previous_signal_wait.get("latest_event_ts") or "").strip()
    previous_next_monitor = _parse_dt(previous_signal_wait.get("next_monitor_after_utc"))
    previous_monitor_completed = _scheduled_monitor_report_completed(
        previous_signal_wait.get("command"),
        scheduled_at=previous_next_monitor,
    )
    preserve_previous_monitor = (
        bool(current_event_key)
        and current_event_key == previous_event_key
        and previous_signal_wait.get("fresh_signal") is not True
        and previous_next_monitor is not None
        and not previous_monitor_completed
    )
    next_monitor = (
        previous_next_monitor.astimezone(UTC)
        if preserve_previous_monitor
        else generated_at.astimezone(UTC) + timedelta(minutes=effective_minutes)
    )
    out = dict(signal_wait)
    out["paper_rehearsal_fast_capture_enabled"] = True
    out["paper_rehearsal_fast_monitor_interval_minutes"] = fast_minutes
    out["original_recommended_monitor_interval_minutes"] = current_recommended
    out["recommended_monitor_interval_minutes"] = round(effective_minutes, 4)
    out["signal_freshness_capture_window_minutes"] = (
        signal_wait.get("signal_freshness_capture_window_minutes") or 15.0
    )
    out["monitor_interval_capped_by_signal_freshness"] = True
    out["monitor_signal_age_alignment"] = "paper_rehearsal_fast_capture_capped_to_fresh_signal_window"
    out["next_monitor_after_utc"] = next_monitor.isoformat()
    out["next_monitor_after_kst"] = next_monitor.astimezone(KST).isoformat()
    out["command"] = _scheduled_signal_monitor_command(
        signal_wait.get("command"),
        scheduled_at=next_monitor,
    ) or signal_wait.get("command")
    out["next_monitor_preserved_from_previous_watch"] = preserve_previous_monitor
    out["previous_monitor_report_completed"] = previous_monitor_completed
    out["next_monitor_anchor"] = (
        "previous_watch_same_latest_signal_event"
        if preserve_previous_monitor
        else "previous_watch_monitor_report_completed"
        if previous_monitor_completed
        else "current_watch_generated_at_plus_fast_monitor_interval"
    )
    out["recommended_action"] = "monitor_bridge_without_forcing_entry_at_paper_rehearsal_fast_cadence"
    out["no_live_order_sent"] = True
    return out


def _int_or_default(value: Any, default: int = 0) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return int(default)


def _bucket_numeric_bounds(value: Any) -> tuple[float | None, float | None]:
    text = str(value or "").strip()
    if not text or "_" not in text:
        return None, None
    suffix = text.rsplit("_", 1)[-1]
    if "-" not in suffix:
        try:
            number = float(suffix)
        except ValueError:
            return None, None
        return number, number
    left, right = suffix.split("-", 1)
    try:
        low = float(left)
    except ValueError:
        low = None
    try:
        high = float(right)
    except ValueError:
        high = None
    return low, high


def _candidate_design_blueprints_from_seed_contexts(
    seed_contexts: Any,
    *,
    top_rejected_soft_contexts: Any = None,
    constraints: dict[str, Any] | None = None,
    dominant_probe_quality_blocker: Any = None,
) -> dict[str, Any]:
    rows = [dict(item) for item in list(seed_contexts or []) if isinstance(item, dict)]
    strict_constraints = dict(constraints or {})
    rejected_reasons = [
        str(dict(item).get("reason") or "")
        for item in list(top_rejected_soft_contexts or [])
        if isinstance(item, dict) and dict(item).get("reason")
    ]
    blueprints: list[dict[str, Any]] = []
    seen_ids: set[str] = set()
    risk_repair_mode = (
        strict_constraints.get("status") == "strict_risk_repair_constraints_required"
        or "drawdown_worsening" in set(strict_constraints.get("remaining_primary_blockers") or [])
    )
    for row in rows[:3]:
        reason = str(row.get("reason") or "").replace("no_trade_", "")
        if reason != "MC12_low_confluence":
            continue
        side = str(row.get("side") or "any").lower()
        regime = str(row.get("regime") or "unknown").lower()
        alignment = str(row.get("side_alignment") or "with_trend")
        execution_context = str(row.get("execution_context") or "normal")
        if not regime or regime == "unknown":
            continue

        score_low, _ = _bucket_numeric_bounds(row.get("score_bucket"))
        edge_low, _ = _bucket_numeric_bounds(row.get("edge_bucket"))
        stack_low, _ = _bucket_numeric_bounds(row.get("reason_stack_bucket"))
        _, extension_high = _bucket_numeric_bounds(row.get("extension_bucket"))
        min_score = max(4, int(score_low or 4))
        min_edge = max(2, int(edge_low or 2))
        min_stack = max(2, int(stack_low or 2))
        max_extension = min(float(extension_high or 1.5), 1.5)
        blueprint_id = f"seeded_mc12_{side}_{regime}_{execution_context}_{alignment}_v1"
        if blueprint_id in seen_ids:
            continue
        seen_ids.add(blueprint_id)
        cooldown_bars = 72
        extension_suffix = int(round(max_extension * 10))
        smoke_candidate_recipe_id = (
            f"seeded_mc12_{regime}_score{min_score}_edge{min_edge}_stack{min_stack}"
            f"_ext{extension_suffix}_cooldown{cooldown_bars}"
        )
        overlay_config = {
            "near_miss_probe_units": 0.00025,
            "near_miss_probe_min_score": min_score,
            "near_miss_probe_min_score_edge": min_edge,
            "near_miss_probe_min_reason_stack": min_stack,
            "near_miss_probe_cooldown_bars": cooldown_bars,
            "near_miss_probe_max_extension_atr": max_extension,
            "near_miss_probe_failure_guard_count": 2,
            "near_miss_probe_failure_guard_window_bars": 1440,
            "near_miss_probe_failure_cooldown_bars": 4320,
            "near_miss_probe_allowed_soft_reasons": ["MC12_low_confluence"],
            "near_miss_probe_allowed_alignments": [alignment],
            "near_miss_probe_allowed_execution_contexts": [execution_context],
            "near_miss_probe_allowed_regimes": [regime],
        }
        cli_overlay_args = [
            "--near-miss-probe-units",
            f"{overlay_config['near_miss_probe_units']:g}",
            "--near-miss-probe-min-score",
            str(overlay_config["near_miss_probe_min_score"]),
            "--near-miss-probe-min-score-edge",
            str(overlay_config["near_miss_probe_min_score_edge"]),
            "--near-miss-probe-min-reason-stack",
            str(overlay_config["near_miss_probe_min_reason_stack"]),
            "--near-miss-probe-cooldown-bars",
            str(overlay_config["near_miss_probe_cooldown_bars"]),
            "--near-miss-probe-max-extension-atr",
            f"{overlay_config['near_miss_probe_max_extension_atr']:g}",
            "--near-miss-probe-failure-guard-count",
            str(overlay_config["near_miss_probe_failure_guard_count"]),
            "--near-miss-probe-failure-guard-window-bars",
            str(overlay_config["near_miss_probe_failure_guard_window_bars"]),
            "--near-miss-probe-failure-cooldown-bars",
            str(overlay_config["near_miss_probe_failure_cooldown_bars"]),
            "--near-miss-probe-allowed-soft-reasons",
            ",".join(overlay_config["near_miss_probe_allowed_soft_reasons"]),
            "--near-miss-probe-allowed-alignments",
            ",".join(overlay_config["near_miss_probe_allowed_alignments"]),
            "--near-miss-probe-allowed-execution-contexts",
            ",".join(overlay_config["near_miss_probe_allowed_execution_contexts"]),
            "--near-miss-probe-allowed-regimes",
            ",".join(overlay_config["near_miss_probe_allowed_regimes"]),
        ]
        risk_repair_variants: list[dict[str, Any]] = []
        if risk_repair_mode and regime == "downtrend":
            risk_repair_selection_args = [
                "--selection-max-reaction-usd",
                "200",
                "--selection-mdd-soft-threshold-pct",
                "20",
                "--selection-mdd-soft-penalty",
                "0.01",
            ]
            for variant_id, variant_overlay in [
                (
                    "seeded_mc12_downtrend_score4_edge2_stack2_ext10_cooldown72",
                    {
                        **overlay_config,
                        "near_miss_probe_max_extension_atr": 1.0,
                    },
                ),
                (
                    "quality_gated_mc12_downtrend_score5_edge2_stack2_ext10",
                    {
                        **overlay_config,
                        "near_miss_probe_min_score": max(5, min_score),
                        "near_miss_probe_max_extension_atr": 1.0,
                    },
                ),
                (
                    "quality_gated_mc12_score5_edge2_stack2_ext10_cooldown144",
                    {
                        **overlay_config,
                        "near_miss_probe_min_score": max(5, min_score),
                        "near_miss_probe_max_extension_atr": 1.0,
                        "near_miss_probe_cooldown_bars": 144,
                    },
                ),
            ]:
                variant_args = [
                    "--near-miss-probe-units",
                    f"{variant_overlay['near_miss_probe_units']:g}",
                    "--near-miss-probe-min-score",
                    str(variant_overlay["near_miss_probe_min_score"]),
                    "--near-miss-probe-min-score-edge",
                    str(variant_overlay["near_miss_probe_min_score_edge"]),
                    "--near-miss-probe-min-reason-stack",
                    str(variant_overlay["near_miss_probe_min_reason_stack"]),
                    "--near-miss-probe-cooldown-bars",
                    str(variant_overlay["near_miss_probe_cooldown_bars"]),
                    "--near-miss-probe-max-extension-atr",
                    f"{variant_overlay['near_miss_probe_max_extension_atr']:g}",
                    "--near-miss-probe-failure-guard-count",
                    str(variant_overlay["near_miss_probe_failure_guard_count"]),
                    "--near-miss-probe-failure-guard-window-bars",
                    str(variant_overlay["near_miss_probe_failure_guard_window_bars"]),
                    "--near-miss-probe-failure-cooldown-bars",
                    str(variant_overlay["near_miss_probe_failure_cooldown_bars"]),
                    "--near-miss-probe-allowed-soft-reasons",
                    ",".join(variant_overlay["near_miss_probe_allowed_soft_reasons"]),
                    "--near-miss-probe-allowed-alignments",
                    ",".join(variant_overlay["near_miss_probe_allowed_alignments"]),
                    "--near-miss-probe-allowed-execution-contexts",
                    ",".join(variant_overlay["near_miss_probe_allowed_execution_contexts"]),
                    "--near-miss-probe-allowed-regimes",
                    ",".join(variant_overlay["near_miss_probe_allowed_regimes"]),
                ]
                risk_repair_variants.append(
                    {
                        "candidate_recipe_id": variant_id,
                        "overlay_config": variant_overlay,
                        "cli_overlay_args": variant_args,
                        "candidate_generation_command_template": shlex.join(
                            [
                                ".venv/bin/python",
                                "scripts/run_market_state_rotation_v6_walk_forward_validation.py",
                                "--source-report",
                                "<source_backtest_report.json>",
                                "--report-dir",
                                f"reports/validation/diagnostics/{variant_id}_full_wfo",
                                *variant_args,
                                *risk_repair_selection_args,
                                "--write-report",
                            ]
                        ),
                        "selection_safety_config": {
                            "selection_max_reaction_usd": 200,
                            "blocks_known_drawdown_worsening_reaction_usd": 350,
                            "selection_mdd_soft_threshold_pct": 20,
                            "selection_mdd_soft_penalty": 0.01,
                        },
                        "validation_only": True,
                        "order_submission_allowed": False,
                    }
                )
        blueprints.append(
            {
                "id": blueprint_id,
                "status": "ready_for_validation_only_research",
                "design_family": "mc12_quality_gated_near_miss_micro_probe",
                "hypothesis": (
                    "restrict_near_miss_probe_to_current_eligible_mc12_seed_context"
                ),
                "source_seed_context": row,
                "target_reason": "MC12_low_confluence",
                "target_side": side,
                "target_regime": regime,
                "target_alignment": alignment,
                "target_execution_context": execution_context,
                "dominant_probe_quality_blocker": dominant_probe_quality_blocker,
                "smoke_candidate_recipe_id": smoke_candidate_recipe_id,
                "risk_repair_candidate_recipe_ids": [
                    item["candidate_recipe_id"] for item in risk_repair_variants
                ],
                "risk_repair_command_templates": risk_repair_variants,
                "overlay_config": overlay_config,
                "cli_overlay_args": cli_overlay_args,
                "candidate_generation_command_template": shlex.join(
                    [
                        ".venv/bin/python",
                        "scripts/run_market_state_rotation_v6_walk_forward_validation.py",
                        "--source-report",
                        "<source_backtest_report.json>",
                        "--report-dir",
                        f"reports/validation/diagnostics/{blueprint_id}_walk_forward",
                        *cli_overlay_args,
                        "--write-report",
                    ]
                ),
                "smoke_validation_command_templates": [
                    {
                        "window_days": 120,
                        "candidate_recipe_id": smoke_candidate_recipe_id,
                        "command": (
                            ".venv/bin/python "
                            "scripts/run_market_state_rotation_v6_near_miss_smoke.py "
                            "--source-backtest-report <source_backtest_report.json> "
                            "--days 120 "
                            f"--report-dir reports/validation/diagnostics/{smoke_candidate_recipe_id}_near_miss_smoke_120d "
                            "--write-report"
                        ),
                        "expected_candidate_row": smoke_candidate_recipe_id,
                        "validation_only": True,
                        "order_submission_allowed": False,
                    },
                    {
                        "window_days": 365,
                        "candidate_recipe_id": smoke_candidate_recipe_id,
                        "command": (
                            ".venv/bin/python "
                            "scripts/run_market_state_rotation_v6_near_miss_smoke.py "
                            "--source-backtest-report <source_backtest_report.json> "
                            "--days 365 "
                            f"--report-dir reports/validation/diagnostics/{smoke_candidate_recipe_id}_near_miss_smoke_365d "
                            "--write-report"
                        ),
                        "expected_candidate_row": smoke_candidate_recipe_id,
                        "validation_only": True,
                        "order_submission_allowed": False,
                    },
                ],
                "acceptance_contract": {
                    "probe_add_delta_min": strict_constraints.get(
                        "must_not_reduce_probe_add_delta_min", 0
                    ),
                    "trade_like_events_delta_min": strict_constraints.get(
                        "must_increase_trade_like_events_delta_min", 1
                    ),
                    "max_drawdown_worsening_pct": strict_constraints.get(
                        "must_keep_max_drawdown_worsening_pct_at_or_below"
                    ),
                    "strict_full_walk_forward_require_nonregressing_activity": True,
                },
                "reject_if": [
                    "probe_add_delta_less_than_0",
                    "trade_like_events_delta_less_than_1",
                    "drawdown_worsening",
                    "activity_inversion_between_smoke_and_full_wfo",
                    "mc04_first_touch_relaxation_added_without_new_365d_evidence",
                    "runtime_filter_change_required",
                ],
                "validation_only": True,
                "runtime_filter_change_allowed": False,
                "paper_or_live_promotion_allowed": False,
                "order_submission_allowed": False,
                "no_live_order_sent": True,
            }
        )
    target_reasons = {
        str(item.get("target_reason") or "")
        for item in blueprints
        if item.get("target_reason")
    }
    excluded_rejected_reasons = sorted(
        {
            reason
            for reason in rejected_reasons
            if reason and reason not in target_reasons
        }
    )
    return {
        "status": "seed_context_blueprints_ready" if blueprints else "no_seed_context_blueprints",
        "blueprint_count": len(blueprints),
        "blueprints": blueprints,
        "shared_safety_rules": [
            "research_and_validation_only",
            "do_not_force_current_fresh_signal",
            "do_not_change_runtime_filters_before_strict_full_wfo_pass",
            "do_not_enable_paper_or_live_promotion_from_blueprint",
            "do_not_submit_live_orders",
        ],
        "target_reasons": sorted(target_reasons),
        "excluded_rejected_context_reasons": excluded_rejected_reasons,
        "validation_only": True,
        "runtime_filter_change_allowed": False,
        "paper_or_live_promotion_allowed": False,
        "order_submission_allowed": False,
        "no_live_order_sent": True,
    }


def _metric_trend_item(*, current: Any, baseline: Any, lower_is_better: bool = True) -> dict[str, Any]:
    current_value = _number_or_none(current)
    baseline_value = _number_or_none(baseline)
    if current_value is None or baseline_value is None:
        return {
            "baseline": baseline_value,
            "current": current_value,
            "delta": None,
            "direction": "insufficient_data",
        }
    delta = round(current_value - baseline_value, 4)
    if abs(delta) < 1e-9:
        direction = "unchanged"
    elif (delta < 0.0 and lower_is_better) or (delta > 0.0 and not lower_is_better):
        direction = "improved"
    else:
        direction = "worsened"
    return {
        "baseline": baseline_value,
        "current": current_value,
        "delta": delta,
        "direction": direction,
    }


def _pre_run_quote_window_capture_outcome(
    *,
    pre_run_wait_plan: dict[str, Any] | None,
    latest_collection: dict[str, Any] | None,
) -> dict[str, Any]:
    plan = dict(pre_run_wait_plan or {})
    collection = dict(latest_collection or {})
    waited = plan.get("actual_sleep_seconds") is not None or plan.get("should_sleep") is True
    if not waited:
        return {
            "status": "not_applicable",
            "reason": "pre_run_quote_window_sleep_not_used",
            "no_live_order_sent": True,
        }

    target_dt = _parse_dt(
        plan.get("target_window_start_utc")
        or plan.get("next_quote_coverage_at")
        or plan.get("next_missing_utc_at")
    )
    target_kind = str(plan.get("next_quote_coverage_kind") or "")
    target_hour = f"{target_dt.hour:02d}" if target_dt is not None else str(plan.get("next_missing_utc_hour") or "")
    target_date = target_dt.date().isoformat() if target_dt is not None else str(plan.get("target_utc_date") or "")
    coverage = dict(collection.get("quote_coverage") or {})
    covered_hours = {str(item).zfill(2) for item in list(coverage.get("utc_hour_of_day_covered") or [])}
    missing_hours = {str(item).zfill(2) for item in list(coverage.get("utc_hour_of_day_missing") or [])}
    captured_rows = _int_or_default(collection.get("captured_quote_rows_this_cycle"), 0)

    if target_kind in {"current_utc_calendar_day", "next_utc_calendar_day", "new_utc_calendar_day"}:
        previous_calendar_day_count = _int_or_default(plan.get("calendar_day_count"), -1)
        current_calendar_day_count = _int_or_default(collection.get("quote_calendar_days"), -1)
        covered_calendar_days_before = {str(item) for item in list(plan.get("covered_calendar_days") or [])}
        if current_calendar_day_count > previous_calendar_day_count >= 0:
            status = "target_calendar_day_captured"
            reason = "quote_calendar_day_count_increased_after_wait"
        elif captured_rows > 0 and target_date and target_date not in covered_calendar_days_before:
            status = "target_calendar_day_sampled"
            reason = "quote_rows_captured_for_previously_uncovered_calendar_day"
        elif target_date and target_date in covered_calendar_days_before:
            status = "target_calendar_day_already_covered_before_wait"
            reason = "wait_plan_target_calendar_day_was_already_in_previous_coverage"
        else:
            status = "target_calendar_day_still_missing_after_wait"
            reason = "quote_calendar_day_count_did_not_increase_after_wait"
        return {
            "status": status,
            "reason": reason,
            "target_quote_coverage_kind": target_kind,
            "target_utc_date": target_date or None,
            "target_window_start_utc": target_dt.isoformat() if target_dt is not None else None,
            "target_window_missed": plan.get("target_window_missed"),
            "captured_quote_rows_this_cycle": captured_rows,
            "previous_quote_calendar_days": previous_calendar_day_count if previous_calendar_day_count >= 0 else None,
            "current_quote_calendar_days": current_calendar_day_count if current_calendar_day_count >= 0 else None,
            "target_calendar_day_covered": status
            in {"target_calendar_day_captured", "target_calendar_day_sampled", "target_calendar_day_already_covered_before_wait"},
            "covered_calendar_days_before_wait": sorted(covered_calendar_days_before),
            "no_live_order_sent": True,
        }

    if not target_hour:
        status = "target_hour_unknown"
        reason = "wait_plan_missing_target_hour"
    elif target_hour in covered_hours:
        status = "target_hour_captured"
        reason = "target_utc_hour_present_in_latest_quote_coverage"
    elif target_hour in missing_hours:
        status = "target_hour_still_missing_after_wait"
        reason = "target_utc_hour_still_reported_missing_after_evidence_run"
    else:
        status = "coverage_data_insufficient"
        reason = "latest_quote_coverage_does_not_include_target_hour_state"

    return {
        "status": status,
        "reason": reason,
        "target_quote_coverage_kind": target_kind or "missing_utc_hour_bucket",
        "target_utc_hour": target_hour or None,
        "target_utc_date": target_date or None,
        "target_window_start_utc": target_dt.isoformat() if target_dt is not None else None,
        "target_window_missed": plan.get("target_window_missed"),
        "captured_quote_rows_this_cycle": captured_rows,
        "target_hour_covered": bool(target_hour and target_hour in covered_hours),
        "target_hour_missing": bool(target_hour and target_hour in missing_hours),
        "covered_utc_hours": sorted(covered_hours),
        "missing_utc_hours": sorted(missing_hours),
        "no_live_order_sent": True,
    }


def _pre_run_wait_force_quote_sample(pre_run_wait_plan: dict[str, Any] | None) -> bool:
    plan = dict(pre_run_wait_plan or {})
    if not plan or plan.get("target_window_missed") is True:
        return False

    status = str(plan.get("status") or "")
    waited_or_open = plan.get("actual_sleep_seconds") is not None or status in {
        "current_quote_window_open",
        "next_quote_coverage_window_reached_or_previous_plan_stale",
    }
    if not waited_or_open:
        return False

    target_kind = str(plan.get("target_quote_coverage_kind") or plan.get("next_quote_coverage_kind") or "")
    coverage_status = str(plan.get("coverage_status") or "")
    reason = str(plan.get("reason") or "")
    return (
        target_kind in {"missing_hour_of_day_balance_bucket", "current_utc_calendar_day", "next_utc_calendar_day"}
        or coverage_status == "current_hour_of_day_balance_open"
        or coverage_status == "current_utc_calendar_day_open"
        or reason == "current_hour_of_day_balance_can_advance_microstructure_coverage"
        or reason == "current_utc_calendar_day_can_advance_microstructure_coverage"
    )


def _recent_quote_rows(rows: list[dict[str, Any]], *, generated_at: datetime, recent_hours: float) -> list[dict[str, Any]]:
    cutoff = generated_at - timedelta(hours=max(0.0, float(recent_hours or 0.0)))
    recent: list[dict[str, Any]] = []
    for row in rows:
        parsed = _parse_dt(row.get("timestamp"))
        if parsed is not None and parsed >= cutoff:
            recent.append(row)
    return recent


def _microstructure_coverage_plan(
    *,
    coverage: dict[str, Any],
    latest_collection: dict[str, Any],
    microstructure_watch: dict[str, Any],
    generated_at: datetime,
    quote_capture_command: str | None,
) -> dict[str, Any]:
    generated_at = generated_at.astimezone(UTC)
    current_hour = generated_at.hour
    current_utc_date = generated_at.date().isoformat()
    missing_hours: list[int] = []
    for raw in list(coverage.get("utc_hour_of_day_missing") or []):
        hour = _int_or_default(raw, -1)
        if 0 <= hour <= 23 and hour not in missing_hours:
            missing_hours.append(hour)
    missing_hours.sort()

    if missing_hours:
        next_delta, next_hour = min(((hour - current_hour) % 24, hour) for hour in missing_hours)
        if next_delta == 0:
            next_utc = generated_at
            wait_minutes = 0.0
        else:
            next_utc = generated_at.replace(minute=0, second=0, microsecond=0) + timedelta(hours=next_delta)
            wait_minutes = round(max((next_utc - generated_at).total_seconds(), 0.0) / 60.0, 2)
    else:
        next_hour = None
        next_utc = None
        wait_minutes = None

    calendar_day_count = _int_or_default(
        microstructure_watch.get("calendar_day_count"),
        _int_or_default(latest_collection.get("quote_calendar_days"), 0),
    )
    covered_calendar_days = {str(item) for item in list(microstructure_watch.get("calendar_days") or [])}
    min_calendar_days = max(
        1,
        _int_or_default(
            microstructure_watch.get("min_calendar_days"),
            _int_or_default(latest_collection.get("quote_min_calendar_days"), 30),
        ),
    )
    distinct_hour_count = _int_or_default(
        microstructure_watch.get("distinct_hour_count"),
        _int_or_default(latest_collection.get("quote_distinct_hours"), 0),
    )
    min_distinct_hours = max(
        1,
        _int_or_default(
            microstructure_watch.get("min_distinct_hours"),
            _int_or_default(latest_collection.get("quote_min_distinct_hours"), 24),
        ),
    )
    eligible_rows = _int_or_default(
        microstructure_watch.get("eligible_row_count"),
        _int_or_default(latest_collection.get("quote_observed"), 0),
    )
    required_rows = max(
        1,
        _int_or_default(
            microstructure_watch.get("required_quote_samples"),
            _int_or_default(latest_collection.get("quote_required"), 300),
        ),
    )

    remaining_calendar_days = max(min_calendar_days - calendar_day_count, 0)
    remaining_distinct_hours = max(min_distinct_hours - distinct_hour_count, 0)
    remaining_quote_samples = max(required_rows - eligible_rows, 0)
    hour_of_day_covered_count = _int_or_default(coverage.get("utc_hour_of_day_covered_count"), 0)
    min_hour_of_day_buckets = 24
    remaining_hour_of_day_buckets = max(min_hour_of_day_buckets - hour_of_day_covered_count, 0)
    hour_of_day_balance_needed = remaining_hour_of_day_buckets > 0 and remaining_distinct_hours <= 0
    current_hour_missing = current_hour in set(missing_hours)
    current_date_missing = remaining_calendar_days > 0 and current_utc_date not in covered_calendar_days
    if remaining_calendar_days > 0:
        if current_date_missing:
            next_calendar_utc = generated_at
            calendar_wait_minutes = 0.0
        else:
            next_calendar_utc = (generated_at + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
            calendar_wait_minutes = round(max((next_calendar_utc - generated_at).total_seconds(), 0.0) / 60.0, 2)
    else:
        next_calendar_utc = None
        calendar_wait_minutes = None
    if remaining_calendar_days <= 0:
        earliest_calendar_completion_utc = None
    elif current_date_missing:
        if remaining_calendar_days <= 1:
            earliest_calendar_completion_utc = generated_at
        else:
            first_future_day = (generated_at + timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0)
            earliest_calendar_completion_utc = first_future_day + timedelta(days=remaining_calendar_days - 2)
    else:
        earliest_calendar_completion_utc = (
            next_calendar_utc + timedelta(days=remaining_calendar_days - 1)
            if next_calendar_utc is not None
            else None
        )
    coverage_candidates: list[tuple[datetime, str]] = []
    if next_utc is not None:
        if remaining_distinct_hours > 0:
            coverage_candidates.append((next_utc, "missing_utc_hour_bucket"))
        elif hour_of_day_balance_needed:
            coverage_candidates.append((next_utc, "missing_hour_of_day_balance_bucket"))
    if next_calendar_utc is not None and remaining_calendar_days > 0:
        coverage_candidates.append(
            (
                next_calendar_utc,
                "current_utc_calendar_day" if current_date_missing else "next_utc_calendar_day",
            )
        )
    if coverage_candidates:
        next_quote_coverage_at, next_quote_coverage_kind = min(coverage_candidates, key=lambda item: item[0])
        next_quote_coverage_wait = round(max((next_quote_coverage_at - generated_at).total_seconds(), 0.0) / 60.0, 2)
    else:
        next_quote_coverage_at = None
        next_quote_coverage_kind = None
        next_quote_coverage_wait = None

    standard_capture_window_open = (
        current_date_missing
        or current_hour_missing
        or (hour_of_day_balance_needed and current_hour_missing)
    )
    sample_count_incomplete = remaining_quote_samples > 0
    time_coverage_incomplete = (
        remaining_calendar_days > 0
        or remaining_distinct_hours > 0
        or remaining_hour_of_day_buckets > 0
    )
    standard_capture_would_skip_duplicate_window = (
        sample_count_incomplete
        and time_coverage_incomplete
        and not standard_capture_window_open
        and next_quote_coverage_at is not None
    )

    if sample_count_incomplete and standard_capture_window_open:
        status = "quote_sample_count_incomplete_current_window_open"
        recommended_action = "collect_quote_samples_now"
        can_collect_now = bool(quote_capture_command)
    elif sample_count_incomplete and standard_capture_would_skip_duplicate_window:
        status = "quote_sample_count_incomplete_waiting_for_next_coverage_window"
        recommended_action = "wait_until_next_quote_coverage_window"
        can_collect_now = False
    elif sample_count_incomplete:
        status = "quote_sample_count_incomplete"
        recommended_action = "collect_quote_samples_now"
        can_collect_now = bool(quote_capture_command)
    elif current_date_missing:
        status = "current_utc_calendar_day_open"
        recommended_action = "collect_current_utc_calendar_day_now"
        can_collect_now = bool(quote_capture_command)
    elif remaining_calendar_days <= 0 and remaining_distinct_hours <= 0:
        status = "coverage_complete"
        recommended_action = "none"
        can_collect_now = False
    elif current_hour_missing:
        if hour_of_day_balance_needed:
            status = "current_hour_of_day_balance_open"
            recommended_action = "collect_current_hour_of_day_balance_now"
        else:
            status = "current_missing_utc_hour_open"
            recommended_action = "collect_current_missing_utc_hour_now"
        can_collect_now = bool(quote_capture_command)
    else:
        status = "waiting_for_next_quote_coverage_window"
        recommended_action = "wait_until_next_quote_coverage_window"
        can_collect_now = False

    return {
        "status": status,
        "generated_at": generated_at.isoformat(),
        "current_utc_date": current_utc_date,
        "current_utc_date_missing": current_date_missing,
        "current_utc_hour": f"{current_hour:02d}",
        "current_utc_hour_missing": current_hour_missing,
        "next_quote_coverage_kind": next_quote_coverage_kind,
        "next_quote_coverage_at": next_quote_coverage_at.isoformat() if next_quote_coverage_at is not None else None,
        "next_quote_coverage_kst_at": next_quote_coverage_at.astimezone(KST).isoformat() if next_quote_coverage_at is not None else None,
        "next_quote_coverage_wait_minutes": next_quote_coverage_wait,
        "next_calendar_day_at": next_calendar_utc.isoformat() if next_calendar_utc is not None else None,
        "next_calendar_kst_at": next_calendar_utc.astimezone(KST).isoformat() if next_calendar_utc is not None else None,
        "next_calendar_wait_minutes": calendar_wait_minutes,
        "earliest_calendar_completion_utc": (
            earliest_calendar_completion_utc.isoformat() if earliest_calendar_completion_utc is not None else None
        ),
        "earliest_calendar_completion_kst": (
            earliest_calendar_completion_utc.astimezone(KST).isoformat()
            if earliest_calendar_completion_utc is not None
            else None
        ),
        "calendar_completion_policy": "one_new_utc_calendar_date_per_day_for_actual_launch_gate",
        "next_missing_utc_hour": f"{next_hour:02d}" if next_hour is not None else None,
        "next_missing_utc_at": next_utc.isoformat() if next_utc is not None else None,
        "next_missing_kst_at": next_utc.astimezone(KST).isoformat() if next_utc is not None else None,
        "wait_minutes": wait_minutes,
        "missing_utc_hour_of_day": [f"{hour:02d}" for hour in missing_hours],
        "remaining_missing_utc_hour_count": len(missing_hours),
        "hour_of_day_covered_count": hour_of_day_covered_count,
        "min_hour_of_day_bucket_count": min_hour_of_day_buckets,
        "remaining_hour_of_day_bucket_count": remaining_hour_of_day_buckets,
        "hour_of_day_balance_needed": hour_of_day_balance_needed,
        "calendar_day_count": calendar_day_count,
        "min_calendar_days": min_calendar_days,
        "covered_calendar_days": sorted(covered_calendar_days),
        "remaining_calendar_days": remaining_calendar_days,
        "distinct_hour_count": distinct_hour_count,
        "min_distinct_hours": min_distinct_hours,
        "remaining_distinct_hours": remaining_distinct_hours,
        "distinct_hour_bucket_count": distinct_hour_count,
        "min_distinct_hour_bucket_count": min_distinct_hours,
        "remaining_distinct_hour_bucket_count": remaining_distinct_hours,
        "coverage_accounting_note": (
            "distinct_hour_bucket_count counts unique UTC hour timestamps for the launch gate; "
            "hour_of_day buckets show 00-23 distribution balance for collection scheduling."
        ),
        "eligible_quote_samples": eligible_rows,
        "required_quote_samples": required_rows,
        "remaining_quote_samples": remaining_quote_samples,
        "sample_count_incomplete": sample_count_incomplete,
        "time_coverage_incomplete": time_coverage_incomplete,
        "standard_capture_window_open": standard_capture_window_open,
        "standard_capture_would_skip_duplicate_window": standard_capture_would_skip_duplicate_window,
        "force_quote_sample_available": bool(quote_capture_command) and sample_count_incomplete,
        "force_quote_sample_policy": (
            "diagnostic_only_does_not_advance_distinct_hour_or_calendar_coverage"
            if standard_capture_would_skip_duplicate_window
            else "not_needed_for_current_window"
        ),
        "can_collect_now": can_collect_now,
        "quote_capture_command": quote_capture_command,
        "recommended_action": recommended_action,
        "no_live_order_sent": True,
    }


def _quote_microstructure_watch(
    *,
    sample_jsonl: Path,
    generated_at: datetime,
    latest_collection: dict[str, Any],
    previous_payload: dict[str, Any],
    recent_hours: float,
    expected_symbol: str = EXPECTED_SYMBOL,
) -> dict[str, Any]:
    rows = _load_jsonl(sample_jsonl)
    expected_symbol_value = str(expected_symbol or EXPECTED_SYMBOL).upper()
    quote_required = max(1, int(latest_collection.get("quote_required") or 300))
    min_calendar_days = max(1, int(latest_collection.get("quote_min_calendar_days") or 30))
    min_distinct_hours = max(1, int(latest_collection.get("quote_min_distinct_hours") or 24))
    audit = build_quote_shadow_audit_report(
        rows,
        input_sample_path=_display_path(sample_jsonl),
        expected_symbol=expected_symbol_value,
        expected_strategy_family=EXPECTED_STRATEGY_FAMILY,
        required_quote_samples=quote_required,
        min_calendar_days=min_calendar_days,
        min_distinct_hours=min_distinct_hours,
        generated_at=generated_at,
    )
    recent_rows = _recent_quote_rows(rows, generated_at=generated_at, recent_hours=recent_hours)
    recent_audit = build_quote_shadow_audit_report(
        recent_rows,
        input_sample_path=_display_path(sample_jsonl),
        expected_symbol=expected_symbol_value,
        expected_strategy_family=EXPECTED_STRATEGY_FAMILY,
        required_quote_samples=1,
        min_calendar_days=1,
        min_distinct_hours=1,
        generated_at=generated_at,
    )
    metrics = dict(audit.get("metrics") or {})
    previous_micro = dict(previous_payload.get("microstructure_watch") or {})
    baseline_metrics = dict(previous_micro.get("baseline_metrics") or metrics)
    trend = {
        "p95_spread_bps": _metric_trend_item(
            current=metrics.get("p95_spread_bps"),
            baseline=baseline_metrics.get("p95_spread_bps"),
        ),
        "p95_market_slippage_bps": _metric_trend_item(
            current=metrics.get("p95_market_slippage_bps"),
            baseline=baseline_metrics.get("p95_market_slippage_bps"),
        ),
        "p95_latency_ms": _metric_trend_item(
            current=metrics.get("p95_latency_ms"),
            baseline=baseline_metrics.get("p95_latency_ms"),
        ),
    }
    blockers = list(audit.get("blockers") or [])
    metric_blockers = [
        item
        for item in blockers
        if item in {"p95_spread_bps_failed", "p95_market_slippage_bps_failed", "p95_latency_ms_failed"}
    ]
    if audit.get("eligible_row_count", 0) <= 0:
        status = "no_quote_shadow_rows"
    elif metric_blockers:
        status = "metric_gate_blocked"
    elif audit.get("overall_status") == "PASS":
        status = "microstructure_gates_passed"
    else:
        status = "collecting_sample_day_hour_coverage"
    return {
        "status": status,
        "audit_status": audit.get("overall_status"),
        "sample_path": _display_path(sample_jsonl),
        "row_count": audit.get("row_count"),
        "eligible_row_count": audit.get("eligible_row_count"),
        "required_quote_samples": audit.get("required_quote_samples"),
        "calendar_day_count": audit.get("calendar_day_count"),
        "min_calendar_days": audit.get("min_calendar_days"),
        "calendar_days": list(audit.get("calendar_days") or []),
        "distinct_hour_count": audit.get("distinct_hour_count"),
        "min_distinct_hours": audit.get("min_distinct_hours"),
        "distinct_hours": list(audit.get("distinct_hours") or []),
        "recent_hours": max(0.0, float(recent_hours or 0.0)),
        "recent_eligible_row_count": recent_audit.get("eligible_row_count"),
        "coverage": dict(audit.get("coverage") or {}),
        "metrics": metrics,
        "recent_metrics": dict(recent_audit.get("metrics") or {}),
        "baseline_metrics": baseline_metrics,
        "metric_trend": trend,
        "gates": dict(audit.get("gates") or {}),
        "blockers": blockers,
        "metric_blockers": metric_blockers,
        "no_live_order_sent": True,
    }


