def _recent_meta_router_promotion_gate(
    *,
    evidence_root: Path,
    current_at: datetime,
    max_age_minutes: float = 1440.0,
) -> dict[str, Any]:
    current = current_at.astimezone(UTC)
    root = _resolve(evidence_root)
    latest_payload: dict[str, Any] = {}
    latest_path: Path | None = None
    latest_generated: datetime | None = None
    for path in root.glob("**/market_state_rotation_v6_meta_router_promotion_gate.json"):
        payload = _read_json(path)
        generated_at = _parse_dt(payload.get("generated_at"))
        if generated_at is None:
            continue
        generated = generated_at.astimezone(UTC)
        if latest_generated is not None and generated <= latest_generated:
            continue
        latest_payload = payload
        latest_path = path
        latest_generated = generated

    if latest_generated is None or latest_path is None:
        return {
            "status": "unavailable",
            "reason": "no_meta_router_promotion_gate_report",
            "max_age_minutes": max(0.0, float(max_age_minutes or 0.0)),
            "stale": True,
            "blocks_live_promotion": True,
            "no_live_order_sent": True,
        }

    age_minutes = (current - latest_generated).total_seconds() / 60.0
    stale = age_minutes < -0.1 or age_minutes > max(0.0, float(max_age_minutes or 0.0))
    readiness = dict(latest_payload.get("readiness") or {})
    candidate = dict(latest_payload.get("candidate") or {})
    execution_audit = dict(candidate.get("execution_change_audit") or {})
    overfit_audit = dict(candidate.get("overfit_audit") or latest_payload.get("overfit_audit") or {})
    conditional_overfit_holdout_audit = dict(
        latest_payload.get("conditional_overfit_holdout_audit") or {}
    )
    conditional_overfit_operator_review = dict(
        latest_payload.get("conditional_overfit_operator_review") or {}
    )
    compare_summary = dict(latest_payload.get("compare_summary") or {})
    readiness_alignment = dict(latest_payload.get("readiness_candidate_alignment") or {})
    candidate_switch_policy = dict(
        latest_payload.get("candidate_switch_policy")
        or compare_summary.get("candidate_switch_policy")
        or {}
    )
    decision = str(latest_payload.get("promotion_decision") or "")
    live_pass_decisions = {
        "tiny_canary_gate_passed_manual_approval_required",
        "full_live_gate_passed_manual_approval_required",
    }
    source_report = str(latest_payload.get("report_path") or _display_path(latest_path))
    expected_operator_lineage_source_report = str(
        latest_payload.get("expected_operator_lineage_source_report") or source_report
    )
    operator_lineage_artifacts = _operator_lineage_artifact_review(
        promotion_gate_report=latest_payload,
        expected_source_promotion_gate_report=expected_operator_lineage_source_report,
        expected_promotion_gate_generated_at=latest_generated.isoformat(),
    )
    conditional_overfit_operator_review_artifacts = _conditional_overfit_operator_review_artifact_review(
        promotion_gate_report=latest_payload,
        expected_source_promotion_gate_report=expected_operator_lineage_source_report,
        expected_promotion_gate_generated_at=latest_generated.isoformat(),
    )
    return {
        "status": "stale" if stale else latest_payload.get("status"),
        "generated_at": latest_generated.isoformat(),
        "age_minutes": round(age_minutes, 3),
        "source_report": _display_path(latest_path),
        "report_path": source_report,
        "expected_operator_lineage_source_report": expected_operator_lineage_source_report,
        "stale": stale,
        "promotion_decision": decision,
        "decision_reasons": list(latest_payload.get("decision_reasons") or []),
        "next_actions": list(latest_payload.get("next_actions") or []),
        "next_blocker": latest_payload.get("next_blocker"),
        "input_operator_lineage_review_report": latest_payload.get("input_operator_lineage_review_report"),
        "input_conditional_overfit_operator_review_report": latest_payload.get(
            "input_conditional_overfit_operator_review_report"
        ),
        "operator_lineage_review_template_report": latest_payload.get(
            "operator_lineage_review_template_report"
        ),
        "operator_lineage_review_skeleton_report": latest_payload.get(
            "operator_lineage_review_skeleton_report"
        ),
        "operator_lineage_review_artifacts": operator_lineage_artifacts,
        "conditional_overfit_operator_review_template_report": latest_payload.get(
            "conditional_overfit_operator_review_template_report"
        ),
        "conditional_overfit_operator_review_skeleton_report": latest_payload.get(
            "conditional_overfit_operator_review_skeleton_report"
        ),
        "conditional_overfit_operator_review_artifacts": conditional_overfit_operator_review_artifacts,
        "readiness_candidate_alignment": readiness_alignment,
        "performance_upgrade_ready": bool(latest_payload.get("performance_upgrade_ready")),
        "performance_delta_status": latest_payload.get("performance_delta_status"),
        "performance_upgrade_blockers": list(latest_payload.get("performance_upgrade_blockers") or []),
        "performance_upgrade_notes": list(latest_payload.get("performance_upgrade_notes") or []),
        "overfit_audit": overfit_audit,
        "overfit_blockers": list(
            latest_payload.get("overfit_blockers") or overfit_audit.get("blockers") or []
        ),
        "conditional_overfit_holdout_audit": conditional_overfit_holdout_audit,
        "conditional_overfit_operator_review": conditional_overfit_operator_review,
        "risk_compression_ready": bool(latest_payload.get("risk_compression_ready")),
        "risk_compression_detected": bool(latest_payload.get("risk_compression_detected")),
        "risk_compression_blockers": list(latest_payload.get("risk_compression_blockers") or []),
        "compare_summary": {
            "performance_upgrade_status": compare_summary.get("performance_upgrade_status"),
            "performance_upgrade_candidate_count": compare_summary.get("performance_upgrade_candidate_count"),
            "performance_upgrade_smoke_candidate_count": compare_summary.get(
                "performance_upgrade_smoke_candidate_count"
            ),
            "risk_compression_status": compare_summary.get("risk_compression_status"),
            "risk_compression_candidate_count": compare_summary.get("risk_compression_candidate_count"),
            "risk_compression_smoke_candidate_count": compare_summary.get(
                "risk_compression_smoke_candidate_count"
            ),
            "risk_compression_formal_tradeoff_count": compare_summary.get(
                "risk_compression_formal_tradeoff_count"
            ),
            "risk_compression_tradeoff_count": compare_summary.get("risk_compression_tradeoff_count"),
            "risk_compression_next_action": compare_summary.get("risk_compression_next_action"),
            "risk_adjusted_compression_status": compare_summary.get(
                "risk_adjusted_compression_status"
            ),
            "risk_adjusted_compression_candidate_count": compare_summary.get(
                "risk_adjusted_compression_candidate_count"
            ),
            "risk_adjusted_compression_smoke_candidate_count": compare_summary.get(
                "risk_adjusted_compression_smoke_candidate_count"
            ),
            "risk_adjusted_compression_next_action": compare_summary.get(
                "risk_adjusted_compression_next_action"
            ),
            "best_performance_upgrade_candidate": dict(
                compare_summary.get("best_performance_upgrade_candidate") or {}
            ),
            "best_performance_upgrade_smoke_candidate": dict(
                compare_summary.get("best_performance_upgrade_smoke_candidate") or {}
            ),
            "best_risk_compression_candidate": dict(
                compare_summary.get("best_risk_compression_candidate") or {}
            ),
            "best_risk_compression_smoke_candidate": dict(
                compare_summary.get("best_risk_compression_smoke_candidate") or {}
            ),
            "best_risk_compression_tradeoff": dict(
                compare_summary.get("best_risk_compression_tradeoff") or {}
            ),
            "best_risk_adjusted_compression_candidate": dict(
                compare_summary.get("best_risk_adjusted_compression_candidate") or {}
            ),
            "best_risk_adjusted_compression_smoke_candidate": dict(
                compare_summary.get("best_risk_adjusted_compression_smoke_candidate") or {}
            ),
            "candidate_switch_policy": dict(candidate_switch_policy),
        },
        "candidate_switch_policy": dict(candidate_switch_policy),
        "candidate": {
            "recipe_id": candidate.get("recipe_id"),
            "decision": candidate.get("decision"),
            "compounded_return_pct": candidate.get("compounded_return_pct"),
            "max_drawdown_pct": candidate.get("max_drawdown_pct"),
            "avg_cost_drag_pct": candidate.get("avg_cost_drag_pct"),
            "trade_like_events": candidate.get("trade_like_events"),
            "return_delta_vs_baseline_pct": candidate.get("return_delta_vs_baseline_pct"),
            "drawdown_delta_vs_baseline_pct": candidate.get("drawdown_delta_vs_baseline_pct"),
            "cost_delta_vs_baseline_pct": candidate.get("cost_delta_vs_baseline_pct"),
            "trade_event_delta_vs_baseline": candidate.get("trade_event_delta_vs_baseline"),
            "execution_change_audit": execution_audit,
            "overfit_audit": overfit_audit,
            "router_modes": dict(candidate.get("router_modes") or {}),
        },
        "readiness": {
            "stage": readiness.get("stage"),
            "ready_for_paper": readiness.get("ready_for_paper") is True,
            "ready_for_tiny_canary": readiness.get("ready_for_tiny_canary") is True,
            "ready_for_full_live": readiness.get("ready_for_full_live") is True,
            "blockers": list(readiness.get("blockers") or []),
            "warnings": list(readiness.get("warnings") or []),
            "deployment_limits": dict(readiness.get("deployment_limits") or {}),
            "execution_parity": dict(readiness.get("execution_parity") or {}),
            "time_substitution_policy": dict(readiness.get("time_substitution_policy") or {}),
            "upgrade_backlog": dict(readiness.get("upgrade_backlog") or {}),
        },
        "blocks_live_promotion": (
            stale
            or latest_payload.get("no_live_order_sent") is not True
            or decision not in live_pass_decisions
        ),
        "order_submission_allowed": False,
        "no_live_order_sent": latest_payload.get("no_live_order_sent") is True,
    }


def _paper_apply_parity_review_state(
    *,
    recent_paper_apply: dict[str, Any],
    recent_paper_review: dict[str, Any],
    recent_parity_review: dict[str, Any],
) -> dict[str, Any]:
    apply_report = dict(recent_paper_apply or {})
    bridge_review = dict(recent_paper_review or {})
    parity = dict(recent_parity_review or {})
    apply_generated = _parse_dt(apply_report.get("generated_at"))
    parity_generated = _parse_dt(parity.get("generated_at"))
    if apply_report.get("status") == "available" and parity_generated is None:
        source_report = apply_report.get("source_report")
        before_report = bridge_review.get("source_report") or "<pre_apply_evidence_report>"
        return {
            "status": "missing_after_recent_paper_apply",
            "blocks_next_paper_apply": True,
            "reason": "recent_paper_apply_requires_post_apply_parity_review",
            "source_report": source_report,
            "recent_paper_apply_report": source_report,
            "recent_paper_bridge_review_report": bridge_review.get("source_report"),
            "recommended_command": (
                ".venv/bin/python scripts/run_market_state_rotation_v6_paper_apply_parity_review.py "
                f"--before-evidence-report {before_report} "
                f"--after-evidence-report {source_report or '<post_apply_evidence_report>'} "
                "--report-dir reports/validation/diagnostics/<paper_apply_parity_review_report_dir> "
                "--write-report"
            ),
            "blockers": ["post_apply_parity_review_missing"],
            "next_actions": ["run_post_apply_parity_review_before_next_paper_apply"],
            "no_live_order_sent": True,
        }
    if (
        apply_generated is not None
        and parity_generated is not None
        and apply_generated.astimezone(UTC) > parity_generated.astimezone(UTC)
    ):
        source_report = apply_report.get("source_report")
        before_report = bridge_review.get("source_report") or "<pre_apply_evidence_report>"
        return {
            "status": "stale_after_recent_paper_apply",
            "blocks_next_paper_apply": True,
            "reason": "latest_paper_apply_is_newer_than_latest_parity_review",
            "source_report": source_report,
            "recent_paper_apply_report": source_report,
            "recent_paper_apply_generated_at": apply_report.get("generated_at"),
            "recent_parity_review_report": parity.get("source_report"),
            "recent_parity_review_generated_at": parity.get("generated_at"),
            "recommended_command": (
                ".venv/bin/python scripts/run_market_state_rotation_v6_paper_apply_parity_review.py "
                f"--before-evidence-report {before_report} "
                f"--after-evidence-report {source_report or '<post_apply_evidence_report>'} "
                "--report-dir reports/validation/diagnostics/<paper_apply_parity_review_report_dir> "
                "--write-report"
            ),
            "blockers": ["post_apply_parity_review_stale"],
            "next_actions": ["rerun_post_apply_parity_review_for_latest_paper_apply"],
            "no_live_order_sent": True,
        }
    return {
        "status": parity.get("status") or "unavailable",
        "blocks_next_paper_apply": parity.get("blocks_next_paper_apply") is True,
        "reason": parity.get("reason"),
        "source_report": parity.get("source_report"),
        "blockers": list(parity.get("blockers") or []),
        "next_actions": list(parity.get("next_actions") or []),
        "no_live_order_sent": parity.get("no_live_order_sent", True) is True,
    }


def _paper_lifecycle_row_diagnostics(
    *,
    latest: dict[str, Any],
    paper_only_rehearsal: dict[str, Any],
    recent_paper_apply: dict[str, Any],
    recent_paper_review: dict[str, Any],
    parity_review_state: dict[str, Any],
    execution_parity_status_summary: dict[str, Any],
) -> dict[str, Any]:
    paper_gate = dict(latest.get("paper_bridge_apply_gate") or {})
    signal_wait = dict(latest.get("signal_wait_plan") or {})
    collection = dict(latest.get("collection_progress") or {})
    rehearsal = dict(paper_only_rehearsal or {})
    apply_report = dict(recent_paper_apply or {})
    bridge_review = dict(recent_paper_review or {})
    parity_review = dict(parity_review_state or {})
    parity = dict(execution_parity_status_summary or {})
    latest_paper_fill_rows = _int_or_default(collection.get("paper_fill_rows"), 0)
    recent_paper_fill_rows = _int_or_default(apply_report.get("paper_fill_rows"), 0)
    actual_lifecycle_rows = _int_or_default(
        rehearsal.get("actual_paper_lifecycle_rows"),
        0,
    )
    eligible_journal_rows = _int_or_default(parity.get("eligible_journal_rows"), 0)
    parity_delta = _int_or_default(parity_review.get("actual_journal_row_delta"), 0)
    parity_new_rows = _int_or_default(parity_review.get("new_journal_row_count"), 0)
    fresh_signal = (
        paper_gate.get("fresh_signal") is True
        or signal_wait.get("fresh_signal") is True
    )
    paper_apply_available = paper_gate.get("can_request_paper_apply_now") is True
    recent_apply_seen = apply_report.get("status") == "available"
    recent_bridge_seen = bridge_review.get("status") == "available"
    parity_review_blocks = parity_review.get("blocks_next_paper_apply") is True
    rows_available = (
        actual_lifecycle_rows > 0
        or latest_paper_fill_rows > 0
        or recent_paper_fill_rows > 0
        or eligible_journal_rows > 0
        or parity_delta > 0
        or parity_new_rows > 0
        or parity_review.get("credit_confirmed") is True
    )
    bridge_status = str(apply_report.get("bridge_status") or "").lower()
    no_open_plan = bridge_status in {
        "no_open_v6_paper_plan",
        "blocked_no_open_v6_paper_plan",
        "paper_apply_no_open_plan_not_credited",
    }
    parity_status = str(parity_review.get("status") or "")
    if rows_available:
        status = "paper_lifecycle_rows_available"
        missing_stage = None
        safe_next_action = "continue_execution_parity_collection_until_sample_floor"
        blockers: list[str] = []
    elif recent_apply_seen and no_open_plan:
        status = "recent_paper_apply_no_open_v6_paper_plan"
        missing_stage = "bridge_apply_no_open_plan"
        safe_next_action = "wait_for_next_add_signal_or_existing_open_paper_plan_before_remove_credit"
        blockers = ["recent_remove_paper_apply_found_no_open_v6_paper_plan"]
    elif recent_apply_seen and parity_status in {
        "missing_after_recent_paper_apply",
        "stale_after_recent_paper_apply",
    }:
        status = "recent_paper_apply_waiting_for_post_apply_parity_review"
        missing_stage = "post_apply_parity_review"
        safe_next_action = (
            list(parity_review.get("next_actions") or [])
            or ["run_post_apply_parity_review_for_latest_paper_apply"]
        )[0]
        blockers = list(parity_review.get("blockers") or ["post_apply_parity_review_missing"])
    elif recent_apply_seen and parity_review_blocks:
        status = "recent_paper_apply_lifecycle_row_blocked_by_parity_review"
        missing_stage = "paper_apply_parity_review"
        safe_next_action = "resolve_paper_apply_parity_review_blocker_before_next_apply"
        blockers = list(parity_review.get("blockers") or ["paper_apply_parity_review_blocker"])
    elif recent_apply_seen:
        status = "recent_paper_apply_lifecycle_row_missing"
        missing_stage = (
            "paper_fill_or_lifecycle_persistence"
            if latest_paper_fill_rows <= 0 and recent_paper_fill_rows <= 0
            else "execution_journal_credit"
        )
        safe_next_action = "inspect_paper_fill_collection_and_execution_journal_before_next_apply"
        blockers = [f"{missing_stage}_missing"]
    elif paper_apply_available:
        status = "paper_apply_available_waiting_for_manual_operator_apply"
        missing_stage = "operator_paper_apply_review"
        safe_next_action = "operator_review_then_manual_paper_apply_only_if_backup_checks_pass"
        blockers = ["manual_paper_apply_not_recorded"]
    elif not fresh_signal:
        status = "waiting_for_fresh_signal_before_first_paper_apply"
        missing_stage = "current_fresh_signal"
        safe_next_action = "monitor_fresh_signal_without_forcing_entry"
        blockers = ["current_fresh_signal", "first_real_paper_lifecycle_row"]
    else:
        status = "waiting_for_paper_apply_report"
        missing_stage = "paper_apply_report"
        safe_next_action = "rerun_paper_bridge_dry_run_and_wait_for_manual_apply_record"
        blockers = ["paper_apply_report_missing"]

    return {
        "status": status,
        "missing_stage": missing_stage,
        "blockers": blockers,
        "fresh_signal": fresh_signal,
        "paper_apply_available_now": paper_apply_available,
        "recent_paper_apply_seen": recent_apply_seen,
        "recent_paper_bridge_review_seen": recent_bridge_seen,
        "recent_parity_review_status": parity_review.get("status"),
        "recent_parity_review_blocks_next_apply": parity_review_blocks,
        "rows_available": rows_available,
        "actual_paper_lifecycle_rows": actual_lifecycle_rows,
        "latest_paper_fill_rows": latest_paper_fill_rows,
        "recent_paper_apply_paper_fill_rows": recent_paper_fill_rows,
        "eligible_journal_rows": eligible_journal_rows,
        "execution_parity_missing_samples": parity.get("missing_samples"),
        "parity_actual_journal_row_delta": parity_review.get("actual_journal_row_delta"),
        "parity_new_journal_row_count": parity_review.get("new_journal_row_count"),
        "recent_paper_apply_report": apply_report.get("source_report"),
        "recent_paper_apply_generated_at": apply_report.get("generated_at"),
        "recent_paper_bridge_review_report": bridge_review.get("source_report"),
        "recent_paper_bridge_review_generated_at": bridge_review.get("generated_at"),
        "recent_parity_review_report": parity_review.get("source_report"),
        "recommended_command": parity_review.get("recommended_command"),
        "safe_next_action": safe_next_action,
        "diagnostic_matrix": {
            "fresh_signal_gate": "passed" if fresh_signal else "waiting",
            "paper_apply_gate": "available" if paper_apply_available else "blocked",
            "paper_apply_execution": (
                "recent_apply_seen" if recent_apply_seen else "no_recent_apply_report"
            ),
            "paper_bridge_review": (
                "recent_review_seen" if recent_bridge_seen else "no_recent_bridge_review"
            ),
            "paper_fill_collection": (
                "rows_present"
                if latest_paper_fill_rows > 0 or recent_paper_fill_rows > 0
                else "zero_rows"
            ),
            "post_apply_parity_review": parity_review.get("status") or "unavailable",
            "execution_journal": (
                "rows_present" if eligible_journal_rows > 0 else "zero_eligible_rows"
            ),
        },
        "stale_signal_apply_allowed": False,
        "auto_apply_allowed": False,
        "force_signal_allowed": False,
        "order_submission_allowed": False,
        "no_live_order_sent": (
            apply_report.get("no_live_order_sent", True) is True
            and bridge_review.get("no_live_order_sent", True) is True
            and parity_review.get("no_live_order_sent", True) is True
        ),
    }


def _execution_parity_evidence_ledger(
    *,
    latest: dict[str, Any],
    paper_lifecycle_row_diagnostics: dict[str, Any],
    recent_paper_apply: dict[str, Any],
    recent_paper_review: dict[str, Any],
    parity_review_state: dict[str, Any],
    execution_parity_status_summary: dict[str, Any],
    previous_payload: dict[str, Any] | None,
    generated_at: datetime,
    max_entries: int = 20,
) -> dict[str, Any]:
    paper_gate = dict(latest.get("paper_bridge_apply_gate") or {})
    lifecycle = dict(paper_lifecycle_row_diagnostics or {})
    apply_report = dict(recent_paper_apply or {})
    bridge_review = dict(recent_paper_review or {})
    parity_review = dict(parity_review_state or {})
    parity = dict(execution_parity_status_summary or {})
    previous = dict(previous_payload or {})
    previous_ledger = dict(previous.get("execution_parity_evidence_ledger") or {})
    previous_entries = [
        dict(item)
        for item in list(previous_ledger.get("entries") or [])
        if isinstance(item, dict)
    ]
    required_samples = _int_or_default(parity.get("required_samples"), 0)
    eligible_rows = _int_or_default(parity.get("eligible_journal_rows"), 0)
    missing_samples = _int_or_default(parity.get("missing_samples"), 0)
    progress_pct = (
        round(min(max(eligible_rows / required_samples, 0.0), 1.0) * 100.0, 3)
        if required_samples > 0
        else (100.0 if missing_samples <= 0 else 0.0)
    )
    parity_delta = _int_or_default(parity_review.get("actual_journal_row_delta"), 0)
    parity_new_rows = _int_or_default(parity_review.get("new_journal_row_count"), 0)
    credit_confirmed = (
        parity_review.get("credit_confirmed") is True
        or parity_delta > 0
        or parity_new_rows > 0
    )
    parity_review_status = str(parity_review.get("status") or "")
    parity_review_available = bool(
        parity_review_status
        not in {
            "",
            "unavailable",
            "missing_after_recent_paper_apply",
            "stale_after_recent_paper_apply",
        }
        or (
            parity_review.get("source_report")
            and parity_review_status
            not in {"missing_after_recent_paper_apply", "stale_after_recent_paper_apply"}
        )
    )
    recent_apply_seen = apply_report.get("status") == "available"
    current_apply_forecast_creditable = parity.get("will_credit_current_apply_after_operator_review") is True

    def _entry_key(entry: dict[str, Any]) -> str:
        return "|".join(
            str(entry.get(part) or "")
            for part in ("event_type", "source_report", "generated_at", "credit_status")
        )

    current_entry: dict[str, Any] | None = None
    if parity_review_available:
        credit_status = (
            "credited"
            if credit_confirmed
            else "blocked"
            if parity_review.get("blocks_next_paper_apply") is True
            else "reviewed_no_credit"
        )
        current_entry = {
            "event_type": "post_apply_parity_review",
            "credit_status": credit_status,
            "status": parity_review.get("status"),
            "generated_at": parity_review.get("generated_at") or generated_at.isoformat(),
            "source_report": parity_review.get("source_report"),
            "recent_paper_apply_report": apply_report.get("source_report"),
            "recent_paper_bridge_review_report": bridge_review.get("source_report"),
            "expected_credit_from_before_forecast": parity_review.get(
                "expected_credit_from_before_forecast"
            ),
            "actual_journal_row_delta": parity_review.get("actual_journal_row_delta"),
            "new_journal_row_count": parity_review.get("new_journal_row_count"),
            "credit_confirmed": credit_confirmed,
            "blockers": list(parity_review.get("blockers") or []),
            "next_actions": list(parity_review.get("next_actions") or []),
            "order_submission_allowed": False,
            "no_live_order_sent": parity_review.get("no_live_order_sent", True) is True,
        }
    elif recent_apply_seen:
        current_entry = {
            "event_type": "paper_apply",
            "credit_status": (
                "pending_post_apply_parity_review"
                if lifecycle.get("missing_stage") == "post_apply_parity_review"
                else "not_creditable_no_open_plan"
                if lifecycle.get("missing_stage") == "bridge_apply_no_open_plan"
                else "pending_execution_journal_credit"
            ),
            "status": apply_report.get("status"),
            "generated_at": apply_report.get("generated_at") or generated_at.isoformat(),
            "source_report": apply_report.get("source_report"),
            "bridge_action": apply_report.get("bridge_action"),
            "bridge_status": apply_report.get("bridge_status"),
            "paper_fill_rows": apply_report.get("paper_fill_rows"),
            "recommended_review_command": parity_review.get("recommended_command"),
            "blockers": list(lifecycle.get("blockers") or []),
            "order_submission_allowed": False,
            "no_live_order_sent": apply_report.get("no_live_order_sent", True) is True,
        }
    elif paper_gate.get("can_request_paper_apply_now") is True or paper_gate.get("fresh_signal") is True:
        current_entry = {
            "event_type": "current_apply_forecast",
            "credit_status": (
                "forecast_creditable_after_operator_review"
                if current_apply_forecast_creditable
                else "forecast_not_creditable"
            ),
            "status": "paper_apply_available" if paper_gate.get("can_request_paper_apply_now") is True else "fresh_signal_seen",
            "generated_at": generated_at.isoformat(),
            "source_report": latest.get("evidence_report"),
            "bridge_action": paper_gate.get("bridge_action"),
            "source_event_key": dict(paper_gate.get("execution_parity_preflight") or {}).get(
                "source_event_key"
            ),
            "will_credit_current_apply_after_operator_review": current_apply_forecast_creditable,
            "blockers": list(dict(paper_gate.get("execution_parity_preflight") or {}).get("blockers") or []),
            "order_submission_allowed": False,
            "no_live_order_sent": True,
        }

    entries_by_key: dict[str, dict[str, Any]] = {}
    for entry in previous_entries:
        entries_by_key[_entry_key(entry)] = entry
    if current_entry is not None:
        entries_by_key[_entry_key(current_entry)] = current_entry
    entries = sorted(
        entries_by_key.values(),
        key=lambda item: str(item.get("generated_at") or ""),
        reverse=True,
    )[: max(1, int(max_entries or 1))]
    latest_entry = entries[0] if entries else None

    if missing_samples <= 0:
        status = "execution_parity_sample_floor_satisfied"
        next_action = "hold_execution_parity_evidence_for_operator_promotion_review"
    elif credit_confirmed:
        status = "execution_parity_credit_recorded"
        next_action = "continue_collecting_reviewed_paper_apply_rows"
    elif parity_review.get("blocks_next_paper_apply") is True:
        status = "execution_parity_credit_blocked_by_review"
        next_action = "resolve_post_apply_parity_review_blocker"
    elif recent_apply_seen and lifecycle.get("missing_stage") == "post_apply_parity_review":
        status = "recent_paper_apply_pending_parity_review"
        next_action = "run_post_apply_parity_review_before_next_paper_apply"
    elif current_apply_forecast_creditable:
        status = "current_apply_forecast_creditable_after_operator_review"
        next_action = "operator_review_then_manual_paper_apply_if_backup_checks_pass"
    elif eligible_rows > 0:
        status = "collecting_execution_parity_rows"
        next_action = "continue_collecting_reviewed_paper_lifecycle_rows"
    else:
        status = "waiting_for_first_creditable_paper_apply"
        next_action = lifecycle.get("safe_next_action") or "wait_for_fresh_signal_and_manual_paper_apply"

    return {
        "status": status,
        "generated_at": generated_at.isoformat(),
        "required_samples": required_samples,
        "eligible_journal_rows": eligible_rows,
        "missing_samples": missing_samples,
        "progress_pct": progress_pct,
        "sample_floor_satisfied": missing_samples <= 0,
        "latest_credit_event": latest_entry,
        "entry_count": len(entries),
        "entries": entries,
        "carried_forward_entry_count": len(previous_entries),
        "recent_paper_apply_seen": recent_apply_seen,
        "recent_paper_apply_report": apply_report.get("source_report"),
        "recent_paper_bridge_review_report": bridge_review.get("source_report"),
        "recent_parity_review_status": parity_review.get("status"),
        "recent_parity_review_report": parity_review.get("source_report"),
        "recent_parity_review_blocks_next_apply": parity_review.get("blocks_next_paper_apply") is True,
        "current_apply_forecast_creditable": current_apply_forecast_creditable,
        "currently_creditable_actions": list(parity.get("currently_creditable_actions") or []),
        "next_creditable_event_types": list(parity.get("next_creditable_event_types") or []),
        "paper_lifecycle_status": lifecycle.get("status"),
        "paper_lifecycle_missing_stage": lifecycle.get("missing_stage"),
        "safe_next_action": next_action,
        "backtest_substitution_allowed": False,
        "synthetic_rows_allowed": False,
        "auto_apply_allowed": False,
        "force_signal_allowed": False,
        "order_submission_allowed": False,
        "no_live_order_sent": (
            parity.get("no_live_order_sent") is not False
            and lifecycle.get("no_live_order_sent") is not False
            and all(entry.get("no_live_order_sent") is not False for entry in entries)
        ),
    }


def _paper_apply_retry_blocker(
    latest: dict[str, Any],
    recent_paper_apply: dict[str, Any],
    recent_paper_review: dict[str, Any] | None = None,
) -> dict[str, Any]:
    apply_gate = dict(latest.get("paper_bridge_apply_gate") or {})
    recent = dict(recent_paper_apply or {})
    if (
        apply_gate.get("can_request_paper_apply_now") is True
        and str(apply_gate.get("bridge_action") or "").lower() == "remove"
        and str(recent.get("bridge_action") or "").lower() == "remove"
        and str(recent.get("bridge_status") or "").lower() == "no_open_v6_paper_plan"
        and recent.get("no_live_order_sent") is True
    ):
        review = dict(recent_paper_review or {})
        recent_generated_at = _parse_dt(review.get("generated_at")) or _parse_dt(recent.get("generated_at"))
        next_monitor_after = (
            recent_generated_at.astimezone(UTC) + timedelta(minutes=15)
            if recent_generated_at is not None
            else None
        )
        return {
            "blocked": True,
            "reason": "recent_remove_paper_apply_found_no_open_v6_paper_plan",
            "source_report": recent.get("source_report"),
            "generated_at": recent.get("generated_at"),
            "age_minutes": recent.get("age_minutes"),
            "bridge_status": recent.get("bridge_status"),
            "bridge_action": recent.get("bridge_action"),
            "next_monitor_after_utc": next_monitor_after.isoformat() if next_monitor_after is not None else None,
            "next_monitor_after_kst": next_monitor_after.astimezone(KST).isoformat()
            if next_monitor_after is not None
            else None,
            "next_action": "wait_for_next_add_signal_or_existing_open_paper_plan_before_reapplying_remove",
            "no_live_order_sent": True,
        }
    return {"blocked": False, "no_live_order_sent": True}


def _continuous_runtime_start(
    *,
    previous_payload: dict[str, Any],
    fallback_started_at: datetime,
    current_at: datetime,
    interval_seconds: float,
    runtime_floor: dict[str, Any] | None = None,
) -> dict[str, Any]:
    previous_completed_at = _parse_dt(previous_payload.get("completed_at"))
    previous_runtime = dict(previous_payload.get("runtime_observation") or {})
    previous_continuous_started_at = _parse_dt(previous_runtime.get("continuous_started_at"))
    candidate = previous_continuous_started_at or fallback_started_at
    continuity = _watch_continuity(
        previous_completed_at=previous_completed_at,
        current_completed_at=current_at,
        interval_seconds=interval_seconds,
        previous_payload=previous_payload,
    )
    gap_reset = continuity.get("status") == "gap_warning"
    continuous_started_at = current_at if gap_reset else candidate
    floor = dict(runtime_floor or {})
    floor_started_at = _parse_dt(floor.get("recovered_continuous_started_at"))
    floor_projected_hours = _number_or_none(floor.get("projected_observed_hours"))
    floor_source_observed_hours = _number_or_none(floor.get("source_observed_hours"))
    previous_floor = dict(previous_runtime.get("runtime_floor") or {})
    previous_floor_source_observed_hours = _number_or_none(previous_floor.get("source_observed_hours"))
    computed_hours = max((current_at.astimezone(UTC) - continuous_started_at.astimezone(UTC)).total_seconds(), 0.0) / 3600.0
    runtime_floor_recovered = False
    runtime_start_clamped = False
    fallback_start = fallback_started_at.astimezone(UTC)
    if not gap_reset and continuous_started_at.astimezone(UTC) < fallback_start:
        if floor_started_at is not None and floor_started_at.astimezone(UTC) >= fallback_start:
            continuous_started_at = floor_started_at.astimezone(UTC)
            runtime_floor_recovered = True
        else:
            continuous_started_at = fallback_start
        runtime_start_clamped = True
        computed_hours = max((current_at.astimezone(UTC) - continuous_started_at.astimezone(UTC)).total_seconds(), 0.0) / 3600.0
    better_floor_than_previous_recovery = bool(
        previous_runtime.get("runtime_floor_recovered") is True
        and floor_source_observed_hours is not None
        and previous_floor_source_observed_hours is not None
        and floor_source_observed_hours > previous_floor_source_observed_hours + 0.1
    )
    if (
        not gap_reset
        and floor_started_at is not None
        and floor_projected_hours is not None
        and (
            (
                floor_started_at.astimezone(UTC) < continuous_started_at.astimezone(UTC)
                and floor_projected_hours > computed_hours + 0.1
            )
            or better_floor_than_previous_recovery
        )
    ):
        continuous_started_at = floor_started_at.astimezone(UTC)
        runtime_floor_recovered = True
    return {
        "continuous_started_at": continuous_started_at,
        "previous_continuous_started_at": previous_continuous_started_at,
        "gap_reset": gap_reset,
        "gap_seconds": continuity.get("gap_seconds"),
        "gap_warning": continuity.get("warning"),
        "warning_threshold_seconds": continuity.get("warning_threshold_seconds"),
        "watch_continuity": continuity,
        "runtime_floor_recovered": runtime_floor_recovered,
        "runtime_start_clamped_to_operation_start": runtime_start_clamped,
        "runtime_floor": floor,
        "no_live_order_sent": True,
    }


